function reservation_card(array $row,string $context=''): void
{
    $id=(int)$row['id'];$alloc=get_allocations($id);$stage=reservation_stay_stage($row,$alloc);$rooms=implode('، ',array_unique(array_column($alloc,'room_name')));[$in,$out]=reservation_date_bounds($alloc);$ledger=LedgerService::summary($id);
    ?><a class="reservation-list-item" href="<?=e(url('reservation',['id'=>$id]))?>"><div class="reservation-item-main"><div class="reservation-item-title"><b><?=e($row['guest_name']??$row['guest_name_snapshot']??'')?></b></div><span><?=e($rooms?:'بدون اتاق')?><?php if($in&&$out):?> · <?=jalali_date($in)?> تا <?=jalali_date($out)?><?php endif;?></span><?php if($context):?><small><?=e($context)?></small><?php endif;?></div><div class="reservation-item-side"><span class="reservation-item-status"><?=reservation_stage_badge($stage)?></span><b><?=money($ledger['total'])?> تومان</b><small><?=$ledger['balance']>0?'مانده '.money($ledger['balance']).' تومان':($ledger['balance']<0?'بستانکار '.money(abs($ledger['balance'])).' تومان':'تسویه')?></small></div></a><?php
}

function page_today(): void
{
    $today=sokna_today();$tomorrow=(new DateTimeImmutable($today))->modify('+1 day')->format('Y-m-d');$after=(new DateTimeImmutable($today))->modify('+2 days')->format('Y-m-d');
    $base='SELECT DISTINCT r.id,r.*,COALESCE(NULLIF(r.guest_name_snapshot,\'\'),g.display_name) guest_name FROM '.table('reservations').' r JOIN '.table('guests').' g ON g.id=r.guest_id JOIN '.table('reservation_rooms').' rr ON rr.reservation_id=r.id WHERE r.status<>\'cancelled\' AND ';
    $q=function(string $where,array $args=[])use($base){$s=db()->prepare($base.$where.' ORDER BY r.updated_at DESC');$s->execute($args);return $s->fetchAll();};
    $arrivals=$q("rr.check_in=? AND r.status='confirmed'",[$today]);$departures=$q("rr.check_out=? AND r.status='confirmed'",[$today]);$present=$q("rr.check_in<=? AND rr.check_out>? AND r.status='confirmed'",[$today,$today]);$presentPeople=0;$peopleStmt=db()->prepare("SELECT COALESCE(SUM(rr.guests_count),0) FROM ".table('reservation_rooms')." rr JOIN ".table('reservations')." r ON r.id=rr.reservation_id WHERE rr.check_in<=? AND rr.check_out>? AND r.status='confirmed'");$peopleStmt->execute([$today,$today]);$presentPeople=(int)$peopleStmt->fetchColumn();
    $holds=$q("r.status='hold' AND rr.check_in<=?",[$after]);
    $attention=[];$seen=[];
    foreach($departures as $r){$id=(int)$r['id'];$alloc=get_allocations($id);[, $reservationOut]=reservation_date_bounds($alloc);if($reservationOut!==$today)continue;$ledger=LedgerService::summary($id);if($ledger['balance']>0){$roomContext=implode('، ',array_unique(array_filter(array_column($alloc,'room_name'))));$attention[]=['type'=>'balance','reservation'=>$r,'room_context'=>$roomContext,'label'=>'خروج نهایی امروز · مانده حساب '.money($ledger['balance']).' تومان'];$seen[$id]=1;}}
    foreach(array_merge($arrivals,$present) as $r){$id=(int)$r['id'];if(isset($seen[$id]))continue;$alloc=get_allocations($id);$ledger=LedgerService::summary($id);if($ledger['balance']>0){$roomContext=implode('، ',array_unique(array_filter(array_column($alloc,'room_name'))));$attention[]=['type'=>'balance','reservation'=>$r,'room_context'=>$roomContext,'label'=>'مانده حساب '.money($ledger['balance']).' تومان'];$seen[$id]=1;}}
    foreach($holds as $r){$id=(int)$r['id'];if(isset($seen[$id]))continue;$alloc=get_allocations($id);[$holdIn]=reservation_date_bounds($alloc);$roomContext=implode('، ',array_unique(array_filter(array_column($alloc,'room_name'))));$holdLabel=$holdIn&&$holdIn<$today?'رزرو در انتظار؛ موعد ورود گذشته':($holdIn===$today?'رزرو در انتظار برای امروز':'رزرو در انتظار نزدیک به ورود');$attention[]=['type'=>'hold','reservation'=>$r,'room_context'=>$roomContext,'label'=>$holdLabel];$seen[$id]=1;}
    $turnovers=same_day_turnovers($today);
    $blocks=db()->prepare('SELECT b.*,rooms.name room_name FROM '.table('room_blocks').' b JOIN '.table('rooms').' rooms ON rooms.id=b.room_id WHERE b.start_date<=? AND b.end_date>? ORDER BY rooms.sort_order');$blocks->execute([$today,$today]);$blocks=$blocks->fetchAll();
    $reminders=[];if(feature_enabled('followup_reminders')){$s=db()->query('SELECT rem.*,r.code,COALESCE(NULLIF(r.guest_name_snapshot,\'\'),g.display_name) guest_name FROM '.table('reminders').' rem JOIN '.table('reservations').' r ON r.id=rem.reservation_id JOIN '.table('guests').' g ON g.id=r.guest_id WHERE rem.done_at IS NULL AND rem.due_at<=NOW() ORDER BY rem.due_at LIMIT 10');$reminders=$s->fetchAll();}
    $services=[];if(feature_enabled('extra_services')){$s=db()->prepare("SELECT rs.*,r.code,COALESCE(NULLIF(r.guest_name_snapshot,''),g.display_name) guest_name FROM ".table('reservation_services')." rs JOIN ".table('reservations')." r ON r.id=rs.reservation_id JOIN ".table('guests')." g ON g.id=r.guest_id WHERE rs.service_date=? AND rs.status IN ('requested','confirmed') ORDER BY rs.service_time,rs.id");$s->execute([$today]);$services=$s->fetchAll();}
    $rooms=get_rooms(true);$freeTonight=0;$freeTomorrow=0;foreach($rooms as $r){if(room_is_free((int)$r['id'],$today,$tomorrow))$freeTonight++;if(room_is_free((int)$r['id'],$tomorrow,$after))$freeTomorrow++;}
    $future=[];for($i=1;$i<=6;$i++){$d=(new DateTimeImmutable($today))->modify('+'.$i.' day')->format('Y-m-d');$s=db()->prepare("SELECT r.status,COUNT(DISTINCT r.id) total FROM ".table('reservations')." r JOIN ".table('reservation_rooms')." rr ON rr.reservation_id=r.id WHERE r.status IN ('confirmed','hold') AND rr.check_in=? GROUP BY r.status");$s->execute([$d]);$counts=['confirmed'=>0,'hold'=>0];foreach($s->fetchAll() as $row)$counts[(string)$row['status']]=(int)$row['total'];$future[]=['date'=>$d,'confirmed'=>$counts['confirmed'],'hold'=>$counts['hold']];}
    render_header('امروز','today');page_header('امروز','ورودها، خروج‌ها و موارد نیازمند رسیدگی · '.jalali_date($today));
    ?><div class="today-workspace"><section class="metric-grid today-summary"><?=metric_card('arrow-in','ورودی قطعی',fa_digits(count($arrivals)),'امروز','success')?><?=metric_card('arrow-out','خروجی',fa_digits(count($departures)),'امروز','accent')?><?=metric_card('guests','مهمان حاضر',fa_digits($presentPeople),'نفر','info')?><?=metric_card('bed','اتاق خالی امشب',fa_digits($freeTonight),'فردا '.fa_digits($freeTomorrow).' اتاق','brand')?></section>
    <section class="panel attention-panel today-priority" id="needs-attention"><header class="panel-head"><div><span class="today-section-kicker">اولویت شیفت</span><h2>نیازمند توجه</h2></div></header><?php if(!$attention&&!$turnovers&&!$blocks&&!$reminders):?><div class="all-clear"><?=ui_icon('check')?><div><b>همه‌چیز مرتب است</b><span>مورد فوری برای پیگیری ندارید.</span></div></div><?php else:?><div class="attention-list"><?php foreach($attention as $a):?><a class="attention-item <?=$a['type']?>" href="<?=e(url('reservation',['id'=>$a['reservation']['id']]))?>"><span class="attention-dot <?=$a['type']?>"></span><div><b><?=e($a['reservation']['guest_name'])?></b><small><?=!empty($a['room_context'])?e((string)$a['room_context']).' · ':''?><?=e($a['label'])?></small></div><?=ui_icon('chevron-left')?></a><?php endforeach;?><?php foreach($turnovers as $turnover):?><a class="attention-item turnover" href="<?=e(url('calendar',['day'=>$today]))?>"><span class="attention-dot turnover"></span><div><b><?=e($turnover['room_name'])?> نیاز به آماده‌سازی دارد</b><small>امروز خروج و ورود قطعی دارد؛ بین دو اقامت آماده‌سازی شود.</small></div><?=ui_icon('chevron-left')?></a><?php endforeach;?><?php foreach($blocks as $b):?><a class="attention-item block" href="<?=e(url('rooms'))?>"><span class="attention-dot block"></span><div><b><?=e($b['room_name'])?> خارج از سرویس</b><small><?=e($b['reason'])?></small></div><?=ui_icon('chevron-left')?></a><?php endforeach;?><?php foreach($reminders as $r):?><a class="attention-item reminder" href="<?=e(url('reservation',['id'=>$r['reservation_id']]))?>"><span class="attention-dot reminder"></span><div><b><?=e($r['guest_name'])?></b><small><?=e($r['note'])?></small></div><?=ui_icon('chevron-left')?></a><?php endforeach;?></div><?php endif;?></section>
    <section class="panel today-operations-panel"><header class="panel-head"><div><span class="today-section-kicker">جریان امروز</span><h2>اقامت‌ها</h2></div><a class="text-link" href="<?=e(url('calendar'))?>">نمای تقویم</a></header><div class="today-operation-grid">
      <section class="today-operation-lane arrival"><header class="today-lane-head"><span class="today-lane-icon"><?=ui_icon('arrow-in')?></span><div><b>ورودی‌ها</b><small>شروع قطعی امروز</small></div><span class="today-lane-count"><?=fa_digits(count($arrivals))?></span></header><div class="reservation-list"><?php if(!$arrivals):?><p class="today-empty">ورودی قطعی نداریم.</p><?php else:foreach($arrivals as $r)reservation_card($r);endif;?></div></section>
      <section class="today-operation-lane departure"><header class="today-lane-head"><span class="today-lane-icon"><?=ui_icon('arrow-out')?></span><div><b>خروج‌ها</b><small>پایان اقامت امروز</small></div><span class="today-lane-count"><?=fa_digits(count($departures))?></span></header><div class="reservation-list"><?php if(!$departures):?><p class="today-empty">خروجی ثبت نشده است.</p><?php else:foreach($departures as $r)reservation_card($r);endif;?></div></section>
      <section class="today-operation-lane staying"><header class="today-lane-head"><span class="today-lane-icon"><?=ui_icon('guests')?></span><div><b>در حال اقامت</b><small>اقامت فعال امروز</small></div><span class="today-lane-count"><?=fa_digits(count($present))?></span></header><div class="reservation-list"><?php if(!$present):?><p class="today-empty">اقامت فعالی نداریم.</p><?php else:foreach($present as $r)reservation_card($r);endif;?></div></section>
    </div></section>
    <?php if($services):?><section class="panel"><header class="panel-head"><div><h2>خدمات امروز</h2><p>خدمات زمان‌دار تأییدشده یا در انتظار هماهنگی.</p></div><a class="text-link" href="<?=e(url('services'))?>">مدیریت خدمات</a></header><div class="service-timeline"><?php foreach($services as $s):?><a href="<?=e(url('reservation',['id'=>$s['reservation_id']]))?>"><time><?=e($s['service_time']?fa_digits(substr((string)$s['service_time'],0,5)):'بدون ساعت')?></time><div><b><?=e($s['name_snapshot'])?></b><span><?=e($s['guest_name'])?> · <?=fa_digits($s['people_count'])?> نفر</span></div><?=badge(service_status_label((string)$s['status']),$s['status']==='confirmed'?'success':'warning')?></a><?php endforeach;?></div></section><?php endif;?>
    <section class="panel future-strip"><header class="panel-head"><h2>چند روز آینده</h2></header><div class="future-days"><?php foreach($future as $f):$j=Jalali::toJalali((int)substr($f['date'],0,4),(int)substr($f['date'],5,2),(int)substr($f['date'],8,2));$futureParts=[];if($f['confirmed'])$futureParts[]=fa_digits($f['confirmed']).' قطعی';if($f['hold'])$futureParts[]=fa_digits($f['hold']).' در انتظار';?><a href="<?=e(url('calendar',['start'=>$f['date']]))?>"><span><?=e(Jalali::weekdayName($j['jy'],$j['jm'],$j['jd']))?></span><b><?=fa_digits($j['jd'])?> <?=month_name($j['jm'])?></b><small><?=$futureParts?implode(' · ',$futureParts):'بدون شروع'?></small></a><?php endforeach;?></div></section></div>
    <?php render_footer();
}

function calendar_period(): array
{
    $today=sokna_today();$start=(string)($_GET['start']??$today);if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$start)){$iso=Jalali::toIso(en_digits($start));$start=$iso?:$today;}$days=(int)($_GET['days']??14);if(!in_array($days,[7,14,30],true))$days=14;$end=(new DateTimeImmutable($start))->modify('+'.$days.' days')->format('Y-m-d');$dates=[];for($i=0;$i<$days;$i++){$iso=(new DateTimeImmutable($start))->modify('+'.$i.' days')->format('Y-m-d');$g=getdate(strtotime($iso));$j=Jalali::toJalali((int)$g['year'],(int)$g['mon'],(int)$g['mday']);$dates[]=['iso'=>$iso,'j'=>$j,'jalali_key'=>sprintf('%04d/%02d/%02d',(int)$j['jy'],(int)$j['jm'],(int)$j['jd']),'weekday'=>Jalali::weekdayName($j['jy'],$j['jm'],$j['jd']),'today'=>$iso===$today];}return [$start,$end,$days,$dates];
}
function page_calendar(): void
{
    [$start,$end,$days,$dates]=calendar_period();$today=sokna_today();$showArchived=is_admin()&&!empty($_GET['archived']);
    $allRooms=get_rooms(false);
    $rs=db()->prepare("SELECT rr.*,r.id reservation_id,r.code,r.status,r.notes reservation_notes,COALESCE(NULLIF(r.guest_name_snapshot,''),g.display_name) guest_name FROM ".table('reservation_rooms')." rr JOIN ".table('reservations')." r ON r.id=rr.reservation_id JOIN ".table('guests')." g ON g.id=r.guest_id WHERE r.status<>'cancelled' AND rr.check_in<? AND rr.check_out>? ORDER BY rr.room_id,rr.check_in,rr.id");$rs->execute([$end,$start]);$byRoom=[];$reservationRows=$rs->fetchAll();foreach($reservationRows as $x)$byRoom[(int)$x['room_id']][]=$x;
    $bs=db()->prepare('SELECT * FROM '.table('room_blocks').' WHERE start_date<? AND end_date>? ORDER BY room_id,start_date');$bs->execute([$end,$start]);$blocks=[];foreach($bs->fetchAll() as $b)$blocks[(int)$b['room_id']][]=$b;
    $periodEvidence=[];foreach(array_keys($byRoom) as $id)$periodEvidence[(int)$id]=true;foreach(array_keys($blocks) as $id)$periodEvidence[(int)$id]=true;
    $rooms=array_values(array_filter($allRooms,static function(array $room)use($showArchived,$periodEvidence,$start,$end,$today):bool{
        if($showArchived)return true;
        if(!room_is_archived_now($room,$today))return true;
        $id=(int)$room['id'];if(isset($periodEvidence[$id]))return true;
        $from=(string)($room['available_from']??'');$retired=(string)($room['retired_from']??'');
        return $retired!==''&&$start<$retired&&($from===''||$end>$from);
    }));
    $calendarOperational=static function(array $room,string $iso)use($periodEvidence,$today):bool{
        if(room_operational_on($room,$iso))return true;
        if(!room_is_archived_now($room,$today)||!isset($periodEvidence[(int)$room['id']])||$iso>=$today)return false;
        $from=(string)($room['available_from']??'');$retired=(string)($room['retired_from']??'');
        return ($from===''||$iso>=$from)&&($retired===''||$iso<$retired);
    };
    $ledgerCache=[];$calendarLedger=static function(int $reservationId)use(&$ledgerCache):array{if(!isset($ledgerCache[$reservationId]))$ledgerCache[$reservationId]=LedgerService::summary($reservationId);return $ledgerCache[$reservationId];};
    $todayArrivals=0;$todayDepartures=0;foreach($reservationRows as $row){if((string)$row['check_in']===$today)$todayArrivals++;if((string)$row['check_out']===$today)$todayDepartures++;}
    $mobileDay=(string)($_GET['day']??sokna_today());if($mobileDay<$start||$mobileDay>=$end)$mobileDay=$start;
    $prev=(new DateTimeImmutable($start))->modify('-'.$days.' days')->format('Y-m-d');$next=$end;$mobilePrevDay=(new DateTimeImmutable($mobileDay))->modify('-1 day')->format('Y-m-d');$mobileNextDay=(new DateTimeImmutable($mobileDay))->modify('+1 day')->format('Y-m-d');$mobilePrevStart=$mobilePrevDay<$start?$mobilePrevDay:$start;$mobileNextStart=$mobileNextDay>=$end?$mobileNextDay:$start;$mobilePrevUrl=url('calendar',['start'=>$mobilePrevStart,'days'=>$days,'day'=>$mobilePrevDay]+($showArchived?['archived'=>1]:[]));$mobileNextUrl=url('calendar',['start'=>$mobileNextStart,'days'=>$days,'day'=>$mobileNextDay]+($showArchived?['archived'=>1]:[]));
