function page_reservation_new(): void
{
    $rooms=get_current_rooms();if(!$rooms){render_header('رزرو جدید','reservation_new');page_header('رزرو جدید');empty_state('اتاق فعالی وجود ندارد','ابتدا از بخش اتاق‌ها یک اتاق فعال بسازید.');render_footer();return;}render_header('رزرو جدید','reservation_new');page_header('رزرو جدید','اقامت، مهمان و ثبت نهایی');$waitlistPrefill=get_open_waitlist_request((int)($_GET['waitlist_id']??0));if($waitlistPrefill):?><div class="inline-alert">اطلاعات درخواست وارد فرم شد. اتاق مناسب را انتخاب کنید.</div><?php endif;reservation_form($rooms,null,[]);$rateOverrides=db()->query('SELECT id,room_id,start_date,end_date,rate_mode,base_rate,extra_person_rate FROM '.table('room_rate_overrides').' ORDER BY start_date DESC,id DESC')->fetchAll();render_footer(false,['rooms'=>$rooms,'rateOverrides'=>$rateOverrides]);
}
function page_reservation_edit(): void
{
    $id=(int)($_GET['id']??0);$r=get_reservation($id);if(!$r){render_utility_status_page(404,'رزرو پیدا نشد','این رزرو وجود ندارد یا دیگر از مسیر فعلی قابل دسترسی نیست.',['tone'=>'info','label'=>'رزرو پیدا نشد','primary'=>['label'=>'بازگشت به رزروها','href'=>url('calendar')]]);}if($r['status']==='cancelled'){flash('error','رزرو لغوشده از فرم عمومی قابل ویرایش نیست.');redirect(url('reservation',['id'=>$id]));}$alloc=get_allocations($id);$stage=reservation_stay_stage($r,$alloc);if(reservation_historical_edit_admin_only($r,$alloc)&&!is_admin()){flash('error','اصلاح رزرو پایان‌یافته فقط برای مدیر مجاز است.');redirect(url('reservation',['id'=>$id]));}$rooms=get_current_rooms();foreach($alloc as $a)if(!array_filter($rooms,fn($x)=>(int)$x['id']===(int)$a['room_id'])){$s=db()->prepare('SELECT * FROM '.table('rooms').' WHERE id=?');$s->execute([$a['room_id']]);if($x=$s->fetch())$rooms[]=$x;}render_header('ویرایش رزرو','reservation_edit');page_header('ویرایش رزرو','',[['label'=>'بازگشت به پرونده','href'=>url('reservation',['id'=>$id])]]);reservation_form($rooms,$r,$alloc);$rateOverrides=db()->query('SELECT id,room_id,start_date,end_date,rate_mode,base_rate,extra_person_rate FROM '.table('room_rate_overrides').' ORDER BY start_date DESC,id DESC')->fetchAll();render_footer(false,['rooms'=>$rooms,'rateOverrides'=>$rateOverrides]);
}

function page_reservation(): void
{
    $id=(int)($_GET['id']??0);$r=get_reservation($id);if(!$r){render_utility_status_page(404,'رزرو پیدا نشد','این رزرو وجود ندارد یا دیگر از مسیر فعلی قابل دسترسی نیست.',['tone'=>'info','label'=>'رزرو پیدا نشد','primary'=>['label'=>'بازگشت به رزروها','href'=>url('calendar')]]);}
    $alloc=get_allocations($id);$services=get_services($id);$payments=get_payments($id);$cafe=feature_enabled('cafe')?get_cafe_charges($id):[];$ledger=LedgerService::summary($id);
    $refundAvailable=max(0,(int)$ledger['paid']);$refundCreditLimit=refund_credit_limit($ledger);$refundUiLimit=is_admin()?$refundAvailable:$refundCreditLimit;
    $stage=reservation_stay_stage($r,$alloc);$serviceHistoricalAdminOnly=reservation_service_financial_admin_only($r,$alloc);$activeServiceCount=count(array_filter($services,static fn(array $service)=>(string)($service['status']??'')!=='cancelled'));$postedCafeCount=count(array_filter($cafe,static fn(array $charge)=>(string)($charge['status']??'')==='posted'));
    [$in,$out]=reservation_date_bounds($alloc);$guestPhone=normalize_phone((string)($r['phone']??''));$messageOptions=reservation_message_options($r,$alloc,$services,$ledger);$noShowEligible=reservation_no_show_eligible($r,$alloc);
    $actions=[];if(can_edit()&&$r['status']!=='cancelled'&&(!reservation_historical_edit_admin_only($r,$alloc)||is_admin()))$actions[]=['label'=>'ویرایش رزرو','href'=>url('reservation_edit',['id'=>$id]),'icon'=>'edit','tone'=>'primary'];$actions[]=['label'=>'ووچر مهمان','href'=>url('voucher',['id'=>$id]),'icon'=>'documents'];
    render_header('رزرو','reservation');page_header('پرونده رزرو','جزئیات اقامت، مهمان و حساب رزرو', $actions);
