    <?php if(can_edit()&&$r['status']!=='cancelled'&&(!$historicalReservation||is_admin())):?><details class="panel danger-zone reservation-side-bottom reservation-cancel-disclosure"><summary class="reservation-cancel-summary"><span><b>لغو رزرو</b><small><?=$historicalReservation?'این اقامت پایان یافته است؛ لغو فقط به‌عنوان اصلاح مدیریتی سابقه انجام شود.':'لغو موجودی اتاق را آزاد می‌کند؛ تراکنش‌های مالی حذف نمی‌شوند.'?></small></span></summary><form method="post" action="<?=e(url('reservation_cancel'))?>" class="stack reservation-cancel-form" data-confirm="رزرو لغو شود؟ پرداخت‌ها و سوابق باقی می‌مانند."><?=csrf_field()?><input type="hidden" name="reservation_id" value="<?=$id?>"><label class="field"><span>علت</span><select name="reason"><option value="guest_cancelled">انصراف مهمان</option><option value="property_cancelled">لغو توسط اقامتگاه</option><option value="entry_error">ثبت اشتباه</option><option value="other">سایر</option></select></label><label class="field"><span>جریمه توافقی</span><input class="money-input" inputmode="numeric" name="penalty" value="0"></label><label class="field"><span><?=$historicalReservation?'دلیل اصلاح *':'توضیح'?></span><textarea name="note" rows="3" <?=$historicalReservation?'required':''?>></textarea></label><button class="btn danger" type="submit"><?=ui_icon('trash')?> لغو رزرو</button></form></details><?php elseif($r['status']==='cancelled'):?><section class="panel danger-zone reservation-side-bottom"><h2><?=$r['cancellation_reason']==='guest_no_show'?'عدم مراجعه':'رزرو لغوشده'?></h2><p><?=e(cancellation_reason_label($r['cancellation_reason']))?><?php if($r['cancellation_note']):?> · <?=e($r['cancellation_note'])?><?php endif;?></p><?php if($r['cancelled_at']):?><small>ثبت: <?=e(jalali_datetime((string)$r['cancelled_at']))?><?php if($r['cancellation_user_name']):?> · <?=e((string)$r['cancellation_user_name'])?><?php endif;?></small><?php endif;?></section><?php endif;?></aside></div><?php render_footer();
