function page_guest_search(): never
{
    $q=trim((string)($_GET['q']??''));header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');
    if(text_length($q)<2){echo json_encode(['items'=>[]],JSON_UNESCAPED_UNICODE);exit;}
    $like='%'.$q.'%';$phone=normalize_phone($q);$phoneLike=$phone!==null&&$phone!==''?'%'.$phone.'%':'__never__';
    $st=db()->prepare('SELECT id,display_name,phone_normalized FROM '.table('guests').' WHERE display_name LIKE ? OR phone_normalized LIKE ? ORDER BY updated_at DESC,id DESC LIMIT 12');$st->execute([$like,$phoneLike]);
    $items=[];foreach($st->fetchAll() as $g)$items[]=['id'=>(int)$g['id'],'name'=>(string)$g['display_name'],'phone'=>local_phone((string)($g['phone_normalized']??''))];
    echo json_encode(['items'=>$items],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;
}

function page_quick_search(): never
{
    $q=trim((string)($_GET['q']??''));header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');
    if(text_length($q)<2){echo json_encode(['items'=>[]],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
    $nameLike='%'.normalize_name_key($q).'%';$rawLike='%'.en_digits($q).'%';$phone=normalize_phone($q);$phoneLike=$phone!==null&&$phone!==''?'%'.$phone.'%':'__never__';$items=[];
    try{
        $g=db()->prepare("SELECT id,display_name,phone_normalized FROM ".table('guests')." WHERE LOWER(REPLACE(REPLACE(display_name,'ي','ی'),'ك','ک')) LIKE ? OR phone_normalized LIKE ? ORDER BY updated_at DESC,id DESC LIMIT 6");$g->execute([$nameLike,$phoneLike]);
        foreach($g->fetchAll() as $row)$items[]=['kind'=>'guest','id'=>(int)$row['id'],'title'=>(string)$row['display_name'],'meta'=>($row['phone_normalized']??'')!==''?fa_digits(local_phone((string)$row['phone_normalized'])):'بدون شماره','href'=>url('guest',['id'=>(int)$row['id']])];
        $r=db()->prepare("SELECT r.id,r.code,COALESCE(NULLIF(r.guest_name_snapshot,''),g.display_name) guest_name,COALESCE(NULLIF(r.phone_snapshot,''),g.phone_normalized) phone,r.status FROM ".table('reservations')." r JOIN ".table('guests')." g ON g.id=r.guest_id WHERE r.code LIKE ? OR LOWER(REPLACE(REPLACE(COALESCE(NULLIF(r.guest_name_snapshot,''),g.display_name),'ي','ی'),'ك','ک')) LIKE ? OR COALESCE(NULLIF(r.phone_snapshot,''),g.phone_normalized) LIKE ? ORDER BY r.updated_at DESC,r.id DESC LIMIT 8");$r->execute([$rawLike,$nameLike,$phoneLike]);
        foreach($r->fetchAll() as $row)$items[]=['kind'=>'reservation','id'=>(int)$row['id'],'title'=>(string)$row['guest_name'],'meta'=>'رزرو '.(string)$row['code'].' · '.reservation_status_label($row),'href'=>url('reservation',['id'=>(int)$row['id']])];
    }catch(Throwable $e){log_exception($e,'quick_search');http_response_code(500);echo json_encode(['items'=>[],'error'=>'search_failed'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
    echo json_encode(['items'=>$items],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;
}

function page_availability_check(): never
{
    header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');$roomId=(int)($_GET['room_id']??0);$in=(string)($_GET['check_in']??'');$out=(string)($_GET['check_out']??'');$exclude=max(0,(int)($_GET['exclude']??0));
    if($roomId<1||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$in)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$out)||$in>=$out){http_response_code(422);echo json_encode(['free'=>false,'message'=>'بازه تاریخ معتبر نیست.'],JSON_UNESCAPED_UNICODE);exit;}
    $roomSt=db()->prepare('SELECT active,available_from,retired_from FROM '.table('rooms').' WHERE id=? LIMIT 1');$roomSt->execute([$roomId]);$room=$roomSt->fetch();if(!$room||!room_accepts_stay($room,$in,$out)){echo json_encode(['free'=>false,'message'=>'این اتاق در بازه انتخاب‌شده داخل چرخه فعالیت نیست.'],JSON_UNESCAPED_UNICODE);exit;}$free=room_is_free($roomId,$in,$out,$exclude?:null);echo json_encode(['free'=>$free,'message'=>$free?'اتاق در این بازه آزاد است.':'این اتاق در بخشی از بازه آزاد نیست.'],JSON_UNESCAPED_UNICODE);exit;
}

function page_reservation_calendar_availability(): never
{
    header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');
    $roomId=(int)($_GET['room_id']??0);$from=(string)($_GET['from']??'');$to=(string)($_GET['to']??'');$exclude=max(0,(int)($_GET['exclude']??0));
    if($roomId<1||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)||$from>=$to){http_response_code(422);echo json_encode(['ok'=>false,'error'=>'invalid_range'],JSON_UNESCAPED_UNICODE);exit;}
    try{$span=(new DateTimeImmutable($from))->diff(new DateTimeImmutable($to));$days=(int)$span->format('%r%a');}catch(Throwable $e){$days=0;}
    if($days<1||$days>1100){http_response_code(422);echo json_encode(['ok'=>false,'error'=>'range_too_large'],JSON_UNESCAPED_UNICODE);exit;}
    $roomSt=db()->prepare('SELECT id,name,active,available_from,retired_from FROM '.table('rooms').' WHERE id=? LIMIT 1');$roomSt->execute([$roomId]);$room=$roomSt->fetch();if(!$room){http_response_code(404);echo json_encode(['ok'=>false,'error'=>'room_not_found'],JSON_UNESCAPED_UNICODE);exit;}
    $ranges=[];
    $sql="SELECT rr.check_in start_date,rr.check_out end_date,r.id reservation_id,r.code reservation_code,r.status,COALESCE(NULLIF(r.guest_name_snapshot,''),g.display_name) guest_name FROM ".table('reservation_rooms')." rr JOIN ".table('reservations')." r ON r.id=rr.reservation_id JOIN ".table('guests')." g ON g.id=r.guest_id WHERE rr.room_id=? AND rr.check_in<? AND rr.check_out>? AND r.status<>'cancelled'";$args=[$roomId,$to,$from];if($exclude>0){$sql.=' AND r.id<>?';$args[]=$exclude;}$sql.=' ORDER BY rr.check_in,rr.check_out';$st=db()->prepare($sql);$st->execute($args);foreach($st->fetchAll() as $r)$ranges[]=['start'=>(string)$r['start_date'],'end'=>(string)$r['end_date'],'type'=>'reservation','label'=>(string)$r['status']==='hold'?'در انتظار رزرو':'رزرو قطعی','guest_name'=>(string)$r['guest_name'],'reservation_id'=>(int)$r['reservation_id'],'reservation_code'=>(string)$r['reservation_code']];
    $st=db()->prepare('SELECT start_date,end_date,reason FROM '.table('room_blocks').' WHERE room_id=? AND start_date<? AND end_date>? ORDER BY start_date,end_date');$st->execute([$roomId,$to,$from]);foreach($st->fetchAll() as $b)$ranges[]=['start'=>(string)$b['start_date'],'end'=>(string)$b['end_date'],'type'=>'block','label'=>'خارج از سرویس'.(trim((string)$b['reason'])!==''?' · '.trim((string)$b['reason']):'')];
    if(!(int)$room['active'])$ranges[]=['start'=>$from,'end'=>$to,'type'=>'lifecycle','label'=>'اتاق غیرفعال است'];
    else{
        $available=trim((string)($room['available_from']??''));if($available!==''&&$from<$available)$ranges[]=['start'=>$from,'end'=>min($to,$available),'type'=>'lifecycle','label'=>'پیش از شروع فعالیت اتاق'];
        $retired=trim((string)($room['retired_from']??''));if($retired!==''&&$to>$retired)$ranges[]=['start'=>max($from,$retired),'end'=>$to,'type'=>'lifecycle','label'=>'پس از خروج اتاق از چرخه'];
    }
    echo json_encode(['ok'=>true,'room_id'=>$roomId,'room_name'=>(string)$room['name'],'from'=>$from,'to'=>$to,'ranges'=>$ranges],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;
}

function page_guests(): void
{
    $q=trim((string)($_GET['q']??''));$filter=(string)($_GET['filter']??'all');if(!in_array($filter,['all','present','future','repeat','missing_phone'],true))$filter='all';$today=sokna_today();
    // Guest directory activity is reservation-derived, but the UI intentionally exposes
    // completed stays rather than raw reservation attempts so "returning guest" stays meaningful.
    $activity='SELECT r.guest_id,COUNT(DISTINCT r.id) reservation_count,COUNT(DISTINCT CASE WHEN r.status=\'confirmed\' AND rr.check_out<=? THEN r.id END) completed_stays,MAX(CASE WHEN r.status=\'confirmed\' AND rr.check_out<=? THEN rr.check_out END) last_checkout,MIN(CASE WHEN r.status IN (\'hold\',\'confirmed\') AND rr.check_in>? THEN rr.check_in END) next_stay,MAX(CASE WHEN r.status=\'confirmed\' AND rr.check_in<=? AND rr.check_out>? THEN 1 ELSE 0 END) present FROM '.table('reservations').' r LEFT JOIN '.table('reservation_rooms').' rr ON rr.reservation_id=r.id GROUP BY r.guest_id';
    $sql='SELECT g.*,COALESCE(a.reservation_count,0) reservation_count,COALESCE(a.completed_stays,0) completed_stays,a.last_checkout,a.next_stay,COALESCE(a.present,0) present FROM '.table('guests').' g LEFT JOIN ('.$activity.') a ON a.guest_id=g.id WHERE 1=1';
    $args=[$today,$today,$today,$today,$today];
    if($q!==''){$n='%'.normalize_name_key($q).'%';$phone=normalize_phone($q);$sql.=' AND (LOWER(REPLACE(REPLACE(g.display_name,\'ي\',\'ی\'),\'ك\',\'ک\')) LIKE ?'.($phone?' OR g.phone_normalized=?':'').')';$args[]=$n;if($phone)$args[]=$phone;}
    if($filter==='present')$sql.=' AND COALESCE(a.present,0)=1';elseif($filter==='future')$sql.=' AND a.next_stay IS NOT NULL';elseif($filter==='repeat')$sql.=' AND COALESCE(a.completed_stays,0)>=2';elseif($filter==='missing_phone')$sql.=' AND (g.phone_normalized IS NULL OR g.phone_normalized=\'\')';
    $sql.=' ORDER BY COALESCE(a.present,0) DESC,a.next_stay IS NULL,a.next_stay,g.updated_at DESC LIMIT 200';
    $st=db()->prepare($sql);$st->execute($args);$guests=$st->fetchAll();
    render_header('مهمانان','guests');page_header('مهمانان','جست‌وجو و دسترسی سریع به پرونده مهمان');?>
    <form class="guest-directory-toolbar" method="get">
        <input type="hidden" name="page" value="guests">
        <label class="field guest-directory-search"><span>جست‌وجوی مهمان</span><span class="search-box"><button class="search-submit" type="submit" aria-label="جست‌وجو"><?=ui_icon('search')?></button><input type="search" name="q" value="<?=e($q)?>" placeholder="نام یا شماره موبایل" autocomplete="off" enterkeyhint="search"></span></label>
        <nav class="filter-segments guest-directory-filters" aria-label="فیلتر مهمانان"><?php foreach(['all'=>'همه','present'=>'حاضر','future'=>'آینده','repeat'=>'بازگشتی','missing_phone'=>'بدون شماره'] as $k=>$label):?><a class="<?=$filter===$k?'active':''?>" href="<?=e(url('guests',['q'=>$q,'filter'=>$k]))?>" <?=$filter===$k?'aria-current="page"':''?>><?=e($label)?></a><?php endforeach;?></nav>
    </form>
    <section class="guest-directory" aria-label="فهرست مهمانان"><?php if(!$guests):?><?php empty_state('مهمانی پیدا نشد','عبارت یا فیلتر دیگری را امتحان کنید.');?><?php else:?><div class="guest-directory-head"><span>مهمان</span><span>تماس</span><span>سابقه</span><span>وضعیت</span><span></span></div><div class="guest-directory-list"><?php guest_directory_rows($guests);?></div><?php endif;?></section><?php render_footer();
}

function page_guest(): void
{
    $id=(int)($_GET['id']??0);$st=db()->prepare('SELECT * FROM '.table('guests').' WHERE id=?');$st->execute([$id]);$g=$st->fetch();if(!$g){render_utility_status_page(404,'مهمان پیدا نشد','این پرونده مهمان وجود ندارد یا دیگر از مسیر فعلی قابل دسترسی نیست.',['tone'=>'info','label'=>'مهمان پیدا نشد','primary'=>['label'=>'بازگشت به مهمانان','href'=>url('guests')]]);}
    $rs=db()->prepare('SELECT r.*,COALESCE(NULLIF(r.guest_name_snapshot,\'\'),?) guest_name FROM '.table('reservations').' r WHERE guest_id=? ORDER BY created_at DESC');$rs->execute([$g['display_name'],$id]);$reservations=$rs->fetchAll();
    $today=sokna_today();$current=[];$future=[];$past=[];$lastCheckout=null;$nextStay=null;$openBalance=0;$completed=0;
    foreach($reservations as $r){$alloc=get_allocations((int)$r['id']);[$rin,$rout]=reservation_date_bounds($alloc);$ledger=LedgerService::summary((int)$r['id']);$openBalance+=max(0,(int)$ledger['balance']);$item=['r'=>$r,'alloc'=>$alloc,'in'=>$rin,'out'=>$rout,'ledger'=>$ledger];
        if($r['status']==='confirmed'&&$rin&&$rout&&$rin<=$today&&$rout>$today)$current[]=$item;
        elseif($r['status']!=='cancelled'&&$rin&&$rin>=$today){$future[]=$item;if($nextStay===null||$rin<$nextStay)$nextStay=$rin;}
        else{$past[]=$item;if($r['status']==='confirmed'&&$rout&&$rout<=$today){$completed++;if($lastCheckout===null||$rout>$lastCheckout)$lastCheckout=$rout;}}
    }
    usort($current,fn($a,$b)=>strcmp((string)($a['in']??''),(string)($b['in']??'')));
    usort($future,fn($a,$b)=>strcmp((string)($a['in']??''),(string)($b['in']??'')));
    usort($past,fn($a,$b)=>strcmp((string)($b['out']??$b['r']['created_at']??''),(string)($a['out']??$a['r']['created_at']??'')));
    $duplicates=[];if($g['phone_normalized']){$d=db()->prepare('SELECT id,display_name,phone_normalized FROM '.table('guests').' WHERE id<>? AND phone_normalized=? LIMIT 10');$d->execute([$id,$g['phone_normalized']]);$duplicates=$d->fetchAll();}
    $phone=normalize_phone((string)($g['phone_normalized']??''));$editable=can_edit();$statusLabel=$current?'اقامت فعال':($future?'رزرو آینده':'بدون اقامت فعال');$statusTone=$current?'success':($future?'info':'neutral');
    $serviceStayItems=array_merge($current,$future);$serviceLink=null;if($editable&&feature_enabled('extra_services')&&$serviceStayItems){$serviceParams=['guest_id'=>$id];if(count($serviceStayItems)===1)$serviceParams['reservation_id']=(int)$serviceStayItems[0]['r']['id'];$serviceLink=url('services',$serviceParams).'#service-add';}
    $guestActions=[];if($editable){$guestActions[]=['label'=>'رزرو جدید','href'=>url('reservation_new',['guest_id'=>$id]),'icon'=>'plus','tone'=>'primary'];if($serviceLink)$guestActions[]=['label'=>'ثبت خدمت','href'=>$serviceLink,'icon'=>'plus','tone'=>'neutral'];}
    render_header('پرونده مهمان','guest');page_header('پرونده مهمان','سابقه، تماس و اطلاعات مهمان',$guestActions);
    guest_profile_overview($g,$statusLabel,$statusTone,$phone,$editable);
    guest_insight_strip($completed,$lastCheckout,$nextStay,$openBalance);
    if(trim((string)($g['notes']??''))!==''):?><section class="guest-note-strip" aria-label="یادداشت مهمان"><span><?=ui_icon('info')?></span><div><b>یادداشت مهمان</b><p><?=nl2br(e((string)$g['notes']))?></p></div></section><?php endif;?>
    <div class="guest-profile-layout">
        <div class="guest-focus-column">
            <section class="panel guest-focus-panel"><header class="panel-head"><div><h2>اقامت فعلی و آینده</h2><p>مهم‌ترین وضعیت عملیاتی این مهمان.</p></div></header><?php if(!$current&&!$future):?><p class="quiet compact-empty">اقامت فعال یا رزرو آینده‌ای ندارد.</p><?php else:?><div class="guest-stay-list"><?php if($current)guest_stay_rows($current);if($future)guest_stay_rows($future);?></div><?php endif;?></section>
        </div>
        <?php guest_profile_record_panel($g,$editable,$duplicates);?>
