    ?><section class="room-v3-editor" id="room-editor" data-room-profile-editor data-mode="<?=$create?'create':'edit'?>"><header class="room-v3-editor-head"><div><a class="room-v3-mobile-back" href="<?=e(url('rooms',['view'=>'rooms']))?>" data-room-back><?=ui_icon('chevron-right')?> اتاق‌ها</a><?php if(!$create):?><span class="eyebrow">مشخصات اتاق</span><?php endif;?><h2><?=$create?'افزودن اتاق':e((string)$room['name'])?></h2><p><?=$create?'نام، ظرفیت و نرخ پایه را وارد کنید.':e(room_bed_summary($room)).' · '.e(room_capacity_summary($room))?></p></div><?php if(!$create):?><?=badge($life,$tone)?><?php endif;?></header><form method="post" action="<?=e(url($action))?>" class="room-v3-form" data-room-profile-form><?=csrf_field()?><?php if(!$create):?><input type="hidden" name="room_id" value="<?=$id?>"><?php endif;?><?php room_profile_form_sections($room,$amenityCatalog,$create);?><footer class="room-v3-editor-actions"><div><a class="btn ghost" href="<?=e(url('rooms',['view'=>'rooms']))?>">انصراف</a><button class="btn primary" type="submit"><?=ui_icon('check')?> <?=$create?'ثبت اتاق':'ذخیره تغییرات'?></button></div></footer></form><?php if(!$create):?><form method="post" action="<?=e(url('room_delete'))?>" class="room-v3-archive-action" data-confirm="این اتاق از فهرست روزمره و تقویم آینده پنهان می‌شود؛ تمام سوابق رزرو و مالی حفظ می‌شوند و امکان بازگشت وجود دارد. ادامه می‌دهید؟"><?=csrf_field()?><input type="hidden" name="room_id" value="<?=$id?>"><button class="btn danger small" type="submit"><?=ui_icon('archive')?> حذف / بایگانی اتاق</button><small>حذف امن و قابل بازگشت؛ سابقه حسابداری پاک نمی‌شود.</small></form><?php room_gallery_form_section($room);room_out_of_service_panel($room,$roomBlocks);endif;?></section><?php
