    ?><details class="room-v3-operation inline-form" id="room-out-of-service"><summary class="disclosure-summary"><span><?=ui_icon('calendar')?> خارج از سرویس</span><small class="disclosure-meta"><?=$filtered?fa_digits(count($filtered)).' بازه':'استثنایی'?></small></summary><div class="room-v3-context-body"><p class="quiet">فقط برای تعمیر یا زمانی که این اتاق موقتاً قابل رزرو نیست.</p><form method="post" action="<?=e(url('room_block_create'))?>" class="form-grid room-v3-block-form"><?=csrf_field()?><input type="hidden" name="room_id" value="<?=$id?>"><label class="field"><span>شروع</span><input class="jalali-date" readonly name="start_date" required></label><label class="field"><span>پایان</span><input class="jalali-date" readonly name="end_date" required></label><label class="field full"><span>علت</span><input name="reason" maxlength="255" required placeholder="مثلاً تعمیر سیستم گرمایش"></label><button class="btn full" type="submit"><?=ui_icon('calendar')?> ثبت خارج از سرویس</button></form><?php if($filtered):?><div class="simple-list room-v3-block-list"><?php foreach($filtered as $b):?><div><span><b><?=jalali_date((string)$b['start_date'])?> تا <?=jalali_date((string)$b['end_date'])?></b><small><?=e((string)$b['reason'])?></small></span><form method="post" action="<?=e(url('room_block_delete'))?>" data-confirm="این بازه خارج از سرویس حذف شود؟"><?=csrf_field()?><input type="hidden" name="block_id" value="<?=$b['id']?>"><input type="hidden" name="room_id" value="<?=$id?>"><button class="icon-btn danger" type="submit" aria-label="حذف بازه"><?=ui_icon('trash')?></button></form></div><?php endforeach;?></div><?php endif;?></div></details><?php
}
function amenity_catalog_admin(string $scope,array $items,string $owner='rooms'): void
{
    $isRoom=$scope==='room';
    $usage=[];
    if($isRoom&&!empty($items)){
        try{$rows=db()->query('SELECT amenity_id,COUNT(*) usage_count FROM '.table('room_amenities').' GROUP BY amenity_id')->fetchAll();foreach($rows as $row)$usage[(int)$row['amenity_id']]=(int)$row['usage_count'];}catch(Throwable $e){}
    }
    $title=$isRoom?'امکانات داخل اتاق':'امکانات مشترک اقامتگاه';
    $hint=$isRoom?'مواردی که در صفحه هر اتاق انتخاب می‌شوند؛ مثل یخچال، سشوار یا تلویزیون.':'امکانات متعلق به کل اقامتگاه؛ مثل حیاط، وای‌فای یا صبحانه.';
    ?><nav class="section-tabs amenity-local-tabs" aria-label="نوع امکانات"><a class="<?=$isRoom?'active':''?>" href="<?=e($owner==='rooms'?url('rooms',['view'=>'amenities','scope'=>'room']):url('amenities',['scope'=>'room']))?>">داخل اتاق</a><a class="<?=!$isRoom?'active':''?>" href="<?=e($owner==='rooms'?url('rooms',['view'=>'amenities','scope'=>'property']):url('amenities',['scope'=>'property']))?>">مشترک اقامتگاه</a></nav><section class="panel amenity-settings-group"><header class="panel-head"><div><h2><?=e($title)?></h2><p><?=e($hint)?></p></div><?=badge(fa_digits(count($items)).' مورد','neutral')?></header><div class="amenity-settings-list"><?php if(!$items):?><p class="quiet compact-empty">هنوز موردی تعریف نشده است.</p><?php endif;?><?php foreach($items as $amenity):$used=$usage[(int)$amenity['id']]??0;?><details class="amenity-settings-item"><summary class="disclosure-summary"><span class="amenity-settings-title"><b><?=e($amenity['name'])?></b><small><?=$isRoom?($used?fa_digits($used).' اتاق':'هنوز به اتاقی وصل نیست'):'ترتیب '.fa_digits((int)$amenity['sort_order'])?></small></span><span class="disclosure-meta"><?=badge(!empty($amenity['active'])?'فعال':'غیرفعال',!empty($amenity['active'])?'success':'neutral')?><?php if(!empty($amenity['public_visible'])):?><?=badge('نمایش به مهمان','info')?><?php endif;?></span></summary><div class="amenity-settings-item-body"><form method="post" action="<?=e(url('amenity_save'))?>" class="form-grid amenity-settings-form"><?=csrf_field()?><input type="hidden" name="amenity_id" value="<?=$amenity['id']?>"><input type="hidden" name="scope" value="<?=e($scope)?>"><input type="hidden" name="return_scope" value="<?=e($scope)?>"><label class="field"><span>نام</span><input name="name" maxlength="100" value="<?=e($amenity['name'])?>" required></label><label class="field"><span>ترتیب نمایش</span><input class="localized-number" name="sort_order" inputmode="numeric" value="<?=e(fa_digits((int)$amenity['sort_order']))?>"></label><label class="check-line"><input type="checkbox" name="active" value="1" <?=!empty($amenity['active'])?'checked':''?>><span>فعال</span></label><label class="check-line"><input type="checkbox" name="public_visible" value="1" <?=!empty($amenity['public_visible'])?'checked':''?>><span>نمایش به مهمان</span></label><button class="btn primary full" type="submit">ذخیره تغییرات</button></form><?php if($isRoom&&$used>0):?><div class="inline-alert info compact-alert"><span>این امکان در <?=fa_digits($used)?> اتاق استفاده شده است. برای حذف، ابتدا آن را از اتاق‌ها بردارید؛ برای پنهان‌کردن موقت می‌توانید غیرفعالش کنید.</span></div><?php else:?><form method="post" action="<?=e(url('amenity_delete'))?>" class="amenity-delete-form" data-confirm="این امکان حذف شود؟"><?=csrf_field()?><input type="hidden" name="amenity_id" value="<?=$amenity['id']?>"><input type="hidden" name="return_scope" value="<?=e($scope)?>"><button class="btn danger small" type="submit"><?=ui_icon('trash')?> حذف این امکان</button></form><?php endif;?></div></details><?php endforeach;?></div><details class="inline-form amenity-add-disclosure"><summary class="disclosure-summary"><span><?=ui_icon('plus')?> افزودن امکان</span><span class="disclosure-meta"><?=e($title)?></span></summary><form method="post" action="<?=e(url('amenity_save'))?>" class="form-grid amenity-add-form"><?=csrf_field()?><input type="hidden" name="scope" value="<?=e($scope)?>"><input type="hidden" name="return_scope" value="<?=e($scope)?>"><label class="field"><span>نام امکان</span><input name="name" maxlength="100" required></label><label class="check-line"><input type="checkbox" name="public_visible" value="1"><span>در معرفی عمومی به مهمان نمایش داده شود</span></label><input type="hidden" name="active" value="1"><button class="btn primary full" type="submit"><?=ui_icon('plus')?> افزودن</button></form></details></section><?php
}

