iv><p class="quiet" data-rate-preview-empty>حداقل یک اتاق را انتخاب کنید.</p><div class="rate-preview-list" data-rate-preview-list></div></div><div class="form-actions full"><button class="btn primary" type="submit"><?=ui_icon('check')?> اعمال قیمت بازه‌ای</button></div></form><?php if($currentRateGroups):?><section class="room-rate-groups"><header><h3>فعال و آینده</h3><span><?=fa_digits(count($currentRateGroups))?> بازه</span></header><div class="simple-list"><?php foreach($currentRateGroups as $g):?><div><span><b><?=e($g['label']?:'بازه ویژه')?> · <?=e(implode('، ',$g['room_names']))?></b><small><?=jalali_date((string)$g['start_date'])?> تا <?=jalali_date((string)$g['end_date'])?> · <?=e(rate_mode_label((string)$g['rate_mode']))?> · <?=money((int)$g['base_rate'])?> تومان</small></span><form method="post" action="<?=e(url('rate_override_delete'))?>" data-confirm="این گروه قیمت بازه‌ای حذف شود؟"><?=csrf_field()?><input type="hidden" name="batch_key" value="<?=e($g['batch_key'])?>"><button class="icon-btn danger" type="submit" aria-label="حذف بازه"><?=ui_icon('trash')?></button></form></div><?php endforeach;?></div></section><?php endif;?><?php if($pastRateGroups):?><details class="history-disclosure"><summary class="disclosure-summary"><span>سوابق قیمت‌های گذشته</span><small class="disclosure-meta"><?=fa_digits(count($pastRateGroups))?> بازه</small></summary><div class="simple-list history-list"><?php foreach($pastRateGroups as $g):?><div><span><b><?=e($g['label']?:'بازه ویژه')?> · <?=e(implode('، ',$g['room_names']))?></b><small><?=jalali_date((string)$g['start_date'])?> تا <?=jalali_date((string)$g['end_date'])?></small></span></div><?php endforeach;?></div></details><?php endif;?></section><?php
