function page_rooms(): void
{
    $allRooms=get_rooms(false);$today=sokna_today();$rooms=array_values(array_filter($allRooms,static fn(array $room): bool=>!room_is_archived_now($room,$today)));$archivedRooms=array_values(array_filter($allRooms,static fn(array $room): bool=>room_is_archived_now($room,$today)));
    $admin=is_admin();$view=in_array((string)($_GET['view']??'pricing'),['pricing','rooms','amenities'],true)?(string)($_GET['view']??'pricing'):'pricing';$mode=(string)($_GET['mode']??'');$scope=in_array((string)($_GET['scope']??'room'),['room','property'],true)?(string)($_GET['scope']??'room'):'room';
    $requestedId=(int)($_GET['room']??0);$selectedId=$requestedId?:((int)($rooms[0]['id']??0));$selected=null;foreach($allRooms as $r)if((int)$r['id']===$selectedId){$selected=$r;break;}if(!$selected&&$rooms){$selected=$rooms[0];$selectedId=(int)$selected['id'];}
    $roomAmenities=$admin?amenity_catalog('room',true):[];$activeRoomAmenities=array_values(array_filter($roomAmenities,fn($a)=>!empty($a['active'])));
    $blocks=[];try{$blocks=db()->query('SELECT * FROM '.table('room_blocks').' ORDER BY start_date DESC,id DESC LIMIT 150')->fetchAll();}catch(Throwable $e){}
    $rateGroups=[];$currentRateGroups=[];$pastRateGroups=[];if($admin){$rows=db()->query('SELECT o.*,r.name room_name FROM '.table('room_rate_overrides').' o JOIN '.table('rooms').' r ON r.id=o.room_id ORDER BY o.start_date DESC,o.id DESC LIMIT 200')->fetchAll();foreach($rows as $o){$key=(string)($o['batch_key']?:str_pad(dechex((int)$o['id']),16,'0',STR_PAD_LEFT));if(!isset($rateGroups[$key]))$rateGroups[$key]=['batch_key'=>$key,'start_date'=>$o['start_date'],'end_date'=>$o['end_date'],'rate_mode'=>$o['rate_mode']??'fixed','base_rate'=>(int)$o['base_rate'],'extra_person_rate'=>(int)$o['extra_person_rate'],'label'=>$o['label'],'room_ids'=>[],'room_names'=>[]];$rateGroups[$key]['room_ids'][]=(int)$o['room_id'];$rateGroups[$key]['room_names'][]=(string)$o['room_name'];}foreach($rateGroups as $g){if((string)$g['end_date']>$today)$currentRateGroups[]=$g;else $pastRateGroups[]=$g;}}
    $mobileRoomFocus=($view==='rooms'&&($mode==='create'||array_key_exists('room',$_GET)))?'editor':'list';$mobilePriceFocus=($view==='pricing'&&$mode===''&&array_key_exists('room',$_GET))?'editor':'list';
    $subtitle=$view==='pricing'?'قیمت‌گذاری روزمره و استثناهای زمانی، جدا از تنظیمات ساختاری اتاق.':($view==='amenities'?'فهرست امکانات داخل اتاق و امکانات مشترک اقامتگاه.':'مشخصات، ظرفیت، امکانات و نمایش عمومی اتاق‌ها.');
    render_header('اتاق‌ها و قیمت‌ها','rooms');page_header('اتاق‌ها و قیمت‌ها',$subtitle);?><div class="rooms-v3" data-rooms-v3 data-mobile-room-focus="<?=e($mobileRoomFocus)?>" data-mobile-price-focus="<?=e($mobilePriceFocus)?>"><?php rooms_workspace_switch($view);?>
    <?php if($view==='amenities'):?>
        <?php if(!$admin):?><?php empty_state('دسترسی فقط برای مدیر','مدیریت فهرست امکانات فقط در اختیار مدیر سامانه است.');?>
        <?php else:?><div class="amenity-settings-workspace rooms-amenities-workspace"><?php amenity_catalog_admin($scope,amenity_catalog($scope,true),'rooms');?></div><?php endif;?>
    <?php elseif($view==='pricing'):?>
        <?php if(!$admin):?><section class="panel"><header class="panel-head"><div><h2>نرخ پایه اتاق‌ها</h2><p>نمایش نرخ‌ها؛ ویرایش فقط در اختیار مدیر است.</p></div></header><div class="rate-board-v3"><?php foreach($rooms as $room):?><div class="rate-board-v3-row readonly"><span><b><?=e($room['name'])?></b><small><?=e(room_capacity_summary($room))?></small></span><strong><?=money((int)$room['base_rate'])?> تومان</strong><strong><?=money((int)$room['extra_person_rate'])?> تومان</strong></div><?php endforeach;?></div></section>
        <?php elseif($mode==='bulk'):?><?php room_bulk_pricing_workspace($rooms);?>
        <?php elseif($mode==='range'):?><?php room_rate_range_workspace($rooms,$currentRateGroups,$pastRateGroups);?>
        <?php else:?><section class="room-pricing-v3"><header class="room-pricing-v3-head"><div><h2>نرخ پایه اتاق‌ها</h2><p>اتاق‌های حذف‌شده / خارج از چرخه در قیمت‌گذاری جاری نمایش داده نمی‌شوند.</p></div><div><a class="btn ghost" href="<?=e(url('rooms',['view'=>'pricing','mode'=>'range']))?>"><?=ui_icon('calendar')?> قیمت بازه‌ای</a><a class="btn ghost" href="<?=e(url('rooms',['view'=>'pricing','mode'=>'bulk']))?>"><?=ui_icon('money')?> تغییر گروهی</a></div></header><div class="room-pricing-v3-layout"><div class="rate-board-v3"><div class="rate-board-v3-header"><span>اتاق</span><span>ظرفیت</span><span>نرخ پایه / شب</span><span>نفر اضافه / شب</span><span></span></div><?php foreach($rooms as $room):?><a class="rate-board-v3-row <?=((int)$room['id']===$selectedId)?'selected':''?>" href="<?=e(url('rooms',['view'=>'pricing','room'=>(int)$room['id']]))?>"><span class="rate-board-room"><b><?=e($room['name'])?></b><small><?=e(room_bed_summary($room))?></small></span><span><?=e(room_capacity_summary($room))?></span><strong><?=money((int)$room['base_rate'])?> تومان</strong><strong><?=((int)$room['max_capacity']>(int)$room['standard_capacity'])?money((int)$room['extra_person_rate']).' تومان':'ندارد'?></strong><span><?=ui_icon('chevron-left')?></span></a><?php endforeach;?></div><?php if($selected&&!room_is_archived_now($selected,$today))room_price_editor($selected);?></div><p class="room-pricing-v3-note">«قیمت بازه‌ای» فقط برای استثنای زمانی است؛ نرخ دائمی اتاق از همین صفحه ویرایش می‌شود.</p></section><?php endif;?>
    <?php else:?>
        <?php if(!$admin):?><section class="panel"><header class="panel-head"><h2>مشخصات اتاق‌ها</h2></header><div class="simple-list"><?php foreach($rooms as $r):?><div><span><b><?=e($r['name'])?></b><small><?=e(room_bed_summary($r))?> · <?=e(room_capacity_summary($r))?></small></span><?=badge(room_lifecycle_label($r),!empty($r['active'])?'success':'neutral')?></div><?php endforeach;?></div></section>
        <?php else:$create=$mode==='create';?><section class="room-setup-v3"><div class="room-setup-v3-layout"><?php room_profile_editor($create?null:$selected,$activeRoomAmenities,$create,$blocks);room_rail($rooms,$selectedId,$create);?></div><?php room_archive_panel($archivedRooms);?></section><?php endif;?>
    <?php endif;?></div><?php render_footer(false,['roomsV3'=>['view'=>$view,'selected'=>$selectedId,'mode'=>$mode]]);
}

function report_period(): array
{
    $default=ReportManager::currentJalaliMonth();
    $defaultTo=(new DateTimeImmutable($default['end']))->modify('-1 day')->format('Y-m-d');
    $readDate=static function(mixed $raw,string $fallback): string {
        if(!is_scalar($raw) || is_bool($raw))return $fallback;
        $input=trim(en_digits((string)$raw));
        if($input==='' || strlen($input)>32)return $fallback;
        if(preg_match('/^\d{4}-\d{2}-\d{2}$/D',$input)) {
            $date=DateTimeImmutable::createFromFormat('!Y-m-d',$input);
            return $date && $date->format('Y-m-d')===$input ? $input : $fallback;
        }
        $converted=Jalali::toIso($input);
        if(!is_string($converted))return $fallback;
        $date=DateTimeImmutable::createFromFormat('!Y-m-d',$converted);
        return $date && $date->format('Y-m-d')===$converted ? $converted : $fallback;
    };
    $from=$readDate($_GET['from']??$default['start'],$default['start']);
    $to=$readDate($_GET['to']??$defaultTo,$defaultTo);
    if($from>$to)[$from,$to]=[$to,$from];
    $end=(new DateTimeImmutable($to))->modify('+1 day')->format('Y-m-d');
    return [$from,$to,$end];
}
function report_reservations(string $from,string $end): array
{
    $s=db()->prepare("SELECT DISTINCT r.id,r.*,COALESCE(NULLIF(r.guest_name_snapshot,''),g.display_name) guest_name,COALESCE(NULLIF(r.phone_snapshot,''),g.phone_normalized) phone FROM ".table('reservations')." r JOIN ".table('guests')." g ON g.id=r.guest_id JOIN ".table('reservation_rooms')." rr ON rr.reservation_id=r.id WHERE rr.check_in<? AND rr.check_out>? ORDER BY r.created_at DESC");$s->execute([$end,$from]);return $s->fetchAll();
}
function reservation_export_guest_count(array $allocations): int
{
    [$in,$out]=reservation_date_bounds($allocations);$peak=0;if($in&&$out){for($d=$in;$d<$out;$d=(new DateTimeImmutable($d))->modify('+1 day')->format('Y-m-d')){$daily=0;foreach($allocations as $a)if((string)$a['check_in']<=$d&&$d<(string)$a['check_out'])$daily+=(int)$a['guests_count'];$peak=max($peak,$daily);}}if($peak===0)foreach($allocations as $a)$peak=max($peak,(int)$a['guests_count']);return $peak;
}
