    $x=new XlsxExporter();$x->addSheet('خلاصه مدیریتی',$managerSheet,['columns'=>[1=>28,2=>20,3=>24,4=>20],'merges'=>['A1:D1','A2:D2','A11:D11'],'freeze_rows'=>2]);$x->addSheet('رزروها',$reservationSheet,['columns'=>[1=>18,2=>24,3=>18,4=>14,5=>15,6=>15,7=>28,8=>14,9=>18,10=>18,11=>18,12=>22,13=>20,14=>36],'freeze_rows'=>1,'auto_filter'=>'A1:N'.count($reservationSheet)]);$tmp=dirname(__DIR__).'/storage/report-'.bin2hex(random_bytes(4)).'.xlsx';$x->save($tmp);header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="sokna-report-'.$from.'-'.$to.'.xlsx"');header('Content-Length: '.filesize($tmp));readfile($tmp);@unlink($tmp);exit;
}

