function page_core_hr(): void
{
    header('Cache-Control: no-store, private, max-age=0');
    header('Referrer-Policy: no-referrer');
    $user=current_user();
    if(!$user){require_login();}
    render_header('پرسنل و حقوق','core_hr');
    page_header('پرسنل و حقوق','دسترسی به پرسنل و حقوق در مرکز سکنا.');
    if(!SoknaCoreClient::connected()):?>
        <section class="panel"><div class="empty-state"><div class="empty-icon"><?=ui_icon('warning')?></div><h2>اتصال مرکز سکنا برقرار نیست</h2><p>سایر بخش‌های اقامتگاه بدون اختلال قابل استفاده هستند.</p><?php if(is_admin()):?><a class="btn primary" href="<?=e(url('core_connection'))?>">تنظیم اتصال</a><?php else:?><a class="btn" href="<?=e(url('today'))?>">بازگشت به امروز</a><?php endif;?></div></section>
    <?php render_footer();return;endif;
    try{
        // Probe is diagnostics-only. Daily handoff goes directly through the signed browser POST contract.
        $handoff=SoknaCoreClient::handoff($user);
        audit('core_handoff_started','integration',null,['local_user_id'=>(int)$user['id'],'context'=>'HOUSE']);
    }catch(Throwable $e){
        log_exception($e,'core_handoff');
        audit('core_handoff_failed','integration',null,['local_user_id'=>(int)$user['id']]);
        ?><section class="panel"><div class="empty-state"><div class="empty-icon"><?=ui_icon('warning')?></div><h2>پرسنل و حقوق موقتاً در دسترس نیست</h2><p><?=e($e instanceof RuntimeException?$e->getMessage():'سایر بخش‌های اقامتگاه بدون اختلال قابل استفاده هستند.')?></p><a class="btn" href="<?=e(url('today'))?>">بازگشت به اقامتگاه</a></div></section><?php render_footer();return;
    }
    ?><section class="panel"><header class="panel-head"><div><h2>ورود امن به مرکز سکنا</h2><p>در حال انتقال هویت حساب شماره <?=tech_value((string)$user['id'])?> با زمینه اقامتگاه.</p></div></header><div class="inline-alert info">در حال انتقال امن…</div><form id="soknaCoreHandoff" method="post" action="<?=e((string)$handoff['target'])?>"><input type="hidden" name="token" value="<?=e((string)$handoff['token'])?>"><noscript><button class="btn primary" type="submit"><?=ui_icon('external')?> ورود به پرسنل و حقوق</button></noscript></form></section><script>requestAnimationFrame(()=>document.getElementById('soknaCoreHandoff')?.submit());</script><?php
    render_footer();
}


function service_reservation_candidates(?int $guestId=null): array
{
    $today=sokna_today();
    $sql="SELECT r.id,r.code,r.status,r.guest_id,COALESCE(NULLIF(r.guest_name_snapshot,''),g.display_name) guest_name,MIN(rr.check_in) check_in,MAX(rr.check_out) check_out,GROUP_CONCAT(DISTINCT COALESCE(NULLIF(rr.room_name_snapshot,''),rooms.name) ORDER BY rooms.sort_order SEPARATOR ' + ') rooms FROM ".table('reservations')." r JOIN ".table('guests')." g ON g.id=r.guest_id JOIN ".table('reservation_rooms')." rr ON rr.reservation_id=r.id JOIN ".table('rooms')." rooms ON rooms.id=rr.room_id WHERE r.status<>'cancelled'";
    $args=[];if($guestId!==null&&$guestId>0){$sql.=' AND r.guest_id=?';$args[]=$guestId;}
    $sql.=" GROUP BY r.id,r.code,r.status,r.guest_id,r.guest_name_snapshot,g.display_name HAVING MAX(rr.check_out)>? ORDER BY CASE WHEN MIN(rr.check_in)<=? AND MAX(rr.check_out)>? THEN 0 ELSE 1 END,MIN(rr.check_in),r.id";
    array_push($args,$today,$today,$today);$st=db()->prepare($sql);$st->execute($args);return $st->fetchAll();
}
function service_reservation_option_label(array $row): string
{
    $dates=(!empty($row['check_in'])&&!empty($row['check_out']))?jalali_date((string)$row['check_in']).' تا '.jalali_date((string)$row['check_out']):'بدون تاریخ';
    $rooms=trim((string)($row['rooms']??''))?:'بدون اتاق';$code=!empty($row['code'])?' · '.reservation_code_text((string)$row['code']):'';
    return (string)$row['guest_name'].' · '.$dates.' · '.$rooms.$code;
}
function service_workspace_rows(string $where,array $args=[]): array
{
    $sql="SELECT rs.*,es.category,es.is_timed,r.code,r.guest_id,COALESCE(NULLIF(r.guest_name_snapshot,''),g.display_name) guest_name FROM ".table('reservation_services')." rs LEFT JOIN ".table('extra_services')." es ON es.id=rs.service_id JOIN ".table('reservations')." r ON r.id=rs.reservation_id JOIN ".table('guests')." g ON g.id=r.guest_id WHERE ".$where." ORDER BY COALESCE(rs.service_date,'9999-12-31'),COALESCE(rs.service_time,'23:59'),rs.id";
    $st=db()->prepare($sql);$st->execute($args);return $st->fetchAll();
}
function service_workspace_item(array $service,bool $showDate=false,bool $needsScheduling=false): void
{
    $alloc=get_allocations((int)$service['reservation_id']);$rooms=implode(' + ',array_values(array_unique(array_filter(array_map(static fn(array $a)=>(string)($a['room_name']??''),$alloc)))));$tone=(string)$service['status']==='done'?'success':((string)$service['status']==='confirmed'?'info':'warning');
    $time=$needsScheduling?'زمان‌بندی نشده':(!empty($service['service_time'])?fa_digits(substr((string)$service['service_time'],0,5)):'بدون ساعت');$date=$showDate&&!empty($service['service_date'])?jalali_date((string)$service['service_date']).' · ':'';$pricing=(string)($service['pricing_type_snapshot']??'fixed');$countMeta=$pricing==='per_person'?fa_digits((int)$service['people_count']).' نفر':($pricing==='quantity'?fa_digits((int)$service['quantity']).' عدد':'');
    ?><a class="service-operation-row" href="<?=e(url('reservation',['id'=>$service['reservation_id']]))?>#reservation-services"><span class="service-operation-time <?=$needsScheduling?'is-warning-meta':''?>"><?=$date?><?=$time?></span><span class="service-operation-main"><span class="service-operation-title"><b><?=e((string)$service['name_snapshot'])?></b><span class="status-slot"><?=badge(service_status_label((string)$service['status']),$tone)?></span></span><small><strong class="service-operation-guest"><?=e((string)$service['guest_name'])?></strong><?=($rooms!==''?' · '.e($rooms):'')?><?=$countMeta!==''?' · '.e($countMeta):''?><?php if(!empty($service['category'])):?> · <?=e(service_category_label((string)$service['category']))?><?php endif;?></small></span><span class="service-operation-arrow" aria-hidden="true"><?=ui_icon('chevron-left')?></span></a><?php
}
function service_add_form(array $catalog,array $options=[]): void
{
    if(!$catalog)return;
    $reservationId=(int)($options['reservation_id']??0);$reservationOptions=(array)($options['reservation_options']??[]);$selectedId=(int)($options['selected_reservation_id']??$reservationId);$historical=!empty($options['historical']);$returnTo=(string)($options['return_to']??'reservation');$submitLabel=(string)($options['submit_label']??'ثبت خدمت / گشت');$initialPricing=(string)($catalog[0]['pricing_type']??'fixed');$initialTimed=!empty($catalog[0]['is_timed']);
    $dateMin=trim((string)($options['date_min']??''));$dateMax=trim((string)($options['date_max']??''));
    if($reservationOptions&&$selectedId>0){foreach($reservationOptions as $option)if((int)($option['id']??0)===$selectedId){$dateMin=(string)($option['check_in']??'');$dateMax=(string)($option['check_out']??'');break;}}
    $rangeLabel=$dateMin!==''&&$dateMax!==''?'مجاز: '.jalali_date($dateMin).' تا '.jalali_date($dateMax):($reservationOptions?'ابتدا اقامت مهمان را انتخاب کنید.':'بازه اقامت در دسترس نیست.');
    $dateDisabled=$dateMin===''||$dateMax==='';
    ?><form method="post" action="<?=e(url('service_add'))?>" class="form-grid service-order-form" data-service-pricing-form data-service-schedule-form data-sensitive-commit><?=csrf_field()?><input type="hidden" name="client_token" value="<?=e(financial_commit_token())?>"><?php if($reservationOptions):?><label class="field full"><span>مهمان و اقامت *</span><select name="reservation_id" required data-choice-mode="browse" data-service-reservation-select><option value="">انتخاب اقامت مهمان</option><?php foreach($reservationOptions as $option):$optionIn=(string)($option['check_in']??'');$optionOut=(string)($option['check_out']??'');$optionRange=$optionIn!==''&&$optionOut!==''?'مجاز: '.jalali_date($optionIn).' تا '.jalali_date($optionOut):'';$choiceSecondary=(trim((string)($option['rooms']??''))?:'بدون اتاق').($optionIn!==''&&$optionOut!==''?' · '.jalali_date($optionIn).' تا '.jalali_date($optionOut):' · بدون تاریخ');$choiceCode=!empty($option['code'])?reservation_code_text((string)$option['code']):'';?><option value="<?=$option['id']?>" data-min-iso="<?=e($optionIn)?>" data-max-iso="<?=e($optionOut)?>" data-date-range-label="<?=e($optionRange)?>" data-choice-primary="<?=e((string)$option['guest_name'])?>" data-choice-secondary="<?=e($choiceSecondary)?>" data-choice-technical="<?=e($choiceCode)?>" <?=$selectedId===(int)$option['id']?'selected':''?>><?=e(service_reservation_option_label($option))?></option><?php endforeach;?></select><small>خدمت به همین رزرو و حساب مالی آن متصل می‌شود.</small></label><?php else:?><input type="hidden" name="reservation_id" value="<?=$reservationId?>"><?php endif;?><?php if($returnTo==='services'):?><input type="hidden" name="return_to" value="services"><?php endif;?><label class="field full"><span>خدمت یا گشت *</span><select name="service_id" data-service-select data-choice-mode="browse" required><?php foreach($catalog as $service):?><option value="<?=$service['id']?>" data-price="<?=$service['default_price']?>" data-pricing="<?=e((string)$service['pricing_type'])?>" data-amount-label="<?=e(service_pricing_amount_label((string)$service['pricing_type']))?>" data-is-timed="<?=!empty($service['is_timed'])?'1':'0'?>" data-choice-primary="<?=e((string)$service['name'])?>"><?=e((string)$service['name'])?></option><?php endforeach;?></select></label><label class="field" data-service-amount-field><span data-service-amount-label><?=e(service_pricing_amount_label($initialPricing))?></span><input class="money-input" inputmode="numeric" name="unit_price" data-service-price value="<?=$catalog[0]['default_price']?>"></label><label class="field"><span>وضعیت</span><select name="status"><option value="requested">درخواست‌شده</option><option value="confirmed">تأییدشده</option><option value="done">انجام‌شده</option></select></label><label class="field service-count-field" data-service-quantity-field <?=$initialPricing==='quantity'?'':'hidden'?>> <span>تعداد</span><input name="quantity" value="1" inputmode="numeric"></label><label class="field service-count-field" data-service-people-field <?=$initialPricing==='per_person'?'':'hidden'?>> <span>تعداد نفر</span><input name="people_count" value="1" inputmode="numeric"></label><label class="field service-date-field"><span data-service-date-label>تاریخ اجرا<?=$initialTimed?' *':''?></span><span class="service-date-control"><input class="jalali-date" readonly name="service_date" data-service-date placeholder="انتخاب تاریخ" <?=$dateMin!==''?'data-min-iso="'.e($dateMin).'"':''?> <?=$dateMax!==''?'data-max-iso="'.e($dateMax).'"':''?> <?=$dateDisabled?'disabled':''?> <?=$initialTimed?'required':''?>><span class="service-date-icon" aria-hidden="true"><?=ui_icon('calendar')?></span></span><small data-service-date-hint data-service-range-label="<?=e($rangeLabel)?>"><?=e($rangeLabel)?><?=$dateDisabled?'':($initialTimed?' · تاریخ اجرا برای این خدمت الزامی است.':' · اگر هنوز مشخص نیست، خالی بگذارید.')?></small></label><label class="field"><span>ساعت (اختیاری)</span><input name="service_time" data-service-time data-time-optional placeholder="۰۹:۳۰" dir="ltr"><small>اگر ساعت را وارد می‌کنید، تاریخ اجرا هم باید انتخاب شده باشد.</small></label><label class="field full"><span>یادداشت</span><input name="notes" maxlength="500" placeholder="مثلاً محل حرکت یا درخواست مهمان"></label><?php if($historical):?><label class="field full"><span>دلیل اصلاح مدیریتی *</span><input name="change_reason" required><small>افزودن خدمت از روز خروج به بعد فقط برای مدیر و با ثبت دلیل مجاز است.</small></label><?php endif;?><button class="btn primary full" type="submit"><?=ui_icon('plus')?> <?=e($submitLabel)?></button></form><?php
}

function page_services(): void
{
    if(!feature_enabled('extra_services')){render_utility_status_page(404,'این قابلیت در حال حاضر فعال نیست','این بخش برای مجموعه فعلی خاموش است یا از تنظیمات غیرفعال شده است.',['tone'=>'info','label'=>'قابلیت غیرفعال','primary'=>['label'=>'بازگشت به پنل','href'=>runtime_base_url('index.php')]]);}
    $catalog=db()->query('SELECT * FROM '.table('extra_services').' ORDER BY active DESC,sort_order,id')->fetchAll();$activeCatalog=array_values(array_filter($catalog,static fn(array $item)=>(int)($item['active']??0)===1));$today=sokna_today();$until=date('Y-m-d',strtotime($today.' +14 days'));
    $todayServices=service_workspace_rows("rs.service_date=? AND rs.status<>'cancelled'",[$today]);
    $upcomingServices=service_workspace_rows("rs.service_date>? AND rs.service_date<=? AND rs.status<>'cancelled'",[$today,$until]);
    $unscheduled=service_workspace_rows("rs.service_date IS NULL AND rs.status IN ('requested','confirmed') AND COALESCE(es.is_timed,0)=1");
    $guestId=max(0,(int)($_GET['guest_id']??0));$reservationId=max(0,(int)($_GET['reservation_id']??0));$openOrder=!empty($_GET['service_add'])||$guestId>0||$reservationId>0;$candidates=service_reservation_candidates($guestId?:null);if($reservationId>0&&!array_filter($candidates,static fn(array $row)=>(int)$row['id']===$reservationId)){$allCandidates=service_reservation_candidates();foreach($allCandidates as $candidate)if((int)$candidate['id']===$reservationId){$candidates=[$candidate];break;}}
    $activeCount=count($activeCatalog);
    render_header('خدمات و گشت‌ها','services');page_header('خدمات و گشت‌ها','اجرای خدمات مهمان‌ها را از یک جا پیگیری کنید؛ هر خدمت به رزرو همان مهمان متصل می‌شود.');
    ?><div class="services-v2-workspace">
        <details class="panel service-order-panel" id="service-add" <?=$openOrder?'open':''?>><summary class="disclosure-summary"><span><b><?=ui_icon('plus')?> ثبت خدمت برای مهمان</b><small>مهمان و اقامت → خدمت یا گشت → جزئیات اجرا</small></span><span class="disclosure-meta"><?=badge(fa_digits(count($candidates)).' اقامت قابل انتخاب',count($candidates)?'info':'neutral')?></span></summary><div class="service-order-body"><?php if(!can_edit()):?><div class="compact-empty"><b>دسترسی ثبت خدمت ندارید</b><span>می‌توانید برنامه خدمات و کاتالوگ را مشاهده کنید.</span></div><?php elseif(!$activeCatalog):?><div class="compact-empty"><b>خدمت فعالی در کاتالوگ نیست</b><span>مدیر ابتدا باید حداقل یک خدمت یا گشت فعال تعریف کند.</span></div><?php elseif(!$candidates):?><div class="compact-empty"><b>اقامت فعال یا آینده‌ای برای ثبت خدمت نیست</b><span>خدمت عملیاتی باید به یک رزرو موجود متصل شود؛ برای اصلاح پرونده‌های قدیمی از خود پرونده رزرو استفاده کنید.</span></div><?php else:service_add_form($activeCatalog,['reservation_options'=>$candidates,'selected_reservation_id'=>$reservationId,'return_to'=>'services','submit_label'=>'ثبت برای مهمان']);endif;?></div></details>
        <div class="service-operations-grid">
            <section class="panel service-operations-panel"><header class="panel-head"><div><h2>امروز</h2><p><?=jalali_date($today)?> · کارهایی که باید امروز پیگیری شوند</p></div><?=badge(fa_digits(count($todayServices)).' مورد',count($todayServices)?'info':'neutral')?></header><div class="service-operation-list"><?php if(!$todayServices):?><div class="compact-empty"><b>خدمتی برای امروز ثبت نشده است</b><span>اگر مهمان درخواستی دارد، از فرم بالای صفحه ثبت کنید.</span></div><?php else:foreach($todayServices as $service)service_workspace_item($service);endif;?></div></section>
            <section class="panel service-operations-panel"><header class="panel-head"><div><h2>۱۴ روز پیش رو</h2><p>برای هماهنگی زودتر با مهمان یا ارائه‌دهنده.</p></div><?=badge(fa_digits(count($upcomingServices)).' مورد',count($upcomingServices)?'info':'neutral')?></header><div class="service-operation-list"><?php if(!$upcomingServices):?><div class="compact-empty"><b>خدمت زمان‌بندی‌شده‌ای در دو هفته آینده نیست</b><span>درخواست‌های بدون تاریخ در بخش بعدی جدا نمایش داده می‌شوند.</span></div><?php else:foreach($upcomingServices as $service)service_workspace_item($service,true);endif;?></div></section>
        </div>
        <div class="service-secondary-grid">
        <?php if($unscheduled):?><section class="panel service-unscheduled-panel"><header class="panel-head"><div><h2>نیاز به زمان‌بندی</h2><p>درخواست‌های زمان‌داری که هنوز تاریخ اجرای مشخص ندارند.</p></div><?=badge(fa_digits(count($unscheduled)).' مورد','warning')?></header><div class="service-operation-list"><?php foreach($unscheduled as $service)service_workspace_item($service,false,true);?></div></section><?php endif;?>
        <details class="panel service-catalog-panel" id="service-catalog"><summary class="disclosure-summary"><span><b>کاتالوگ خدمات و گشت‌ها</b><small>تعریف، قیمت پیش‌فرض و ارائه‌دهنده</small></span><span class="disclosure-meta"><?=badge(fa_digits($activeCount).' فعال','success')?><?=badge(fa_digits(count($catalog)).' کل','neutral')?></span></summary><div class="service-catalog-body"><?php if(is_admin()):?><details class="inline-form service-create-disclosure"><summary class="disclosure-summary"><span><?=ui_icon('plus')?> تعریف خدمت یا گشت جدید</span><span class="disclosure-meta">مدیریتی</span></summary><form method="post" action="<?=e(url('service_catalog_save'))?>" class="form-grid service-catalog-form"><?=csrf_field()?><?php service_catalog_fields([]);?><button class="btn primary full" type="submit"><?=ui_icon('plus')?> ساخت خدمت</button></form></details><?php endif;?><div class="service-catalog"><?php if(!$catalog):?><div class="compact-empty"><b>هنوز خدمتی تعریف نشده است</b><span><?=is_admin()?'اولین خدمت را از گزینه بالا تعریف کنید.':'مدیر سامانه هنوز کاتالوگ خدمات را تعریف نکرده است.'?></span></div><?php else:foreach($catalog as $service):?><?php if(is_admin()):?><details class="catalog-item service-catalog-item"><summary class="disclosure-summary"><span class="service-catalog-title"><b><?=e($service['name'])?></b><small><?=e(service_category_label((string)$service['category']))?> · <?=e(pricing_type_label((string)$service['pricing_type']))?></small></span><span class="disclosure-meta"><strong><?=money($service['default_price'])?> تومان</strong><?=badge((int)$service['active']?'فعال':'غیرفعال',(int)$service['active']?'success':'neutral')?></span></summary><form method="post" action="<?=e(url('service_catalog_save'))?>" class="form-grid service-catalog-form"><?=csrf_field()?><input type="hidden" name="service_id" value="<?=$service['id']?>"><?php service_catalog_fields($service);?><button class="btn primary full" type="submit"><?=ui_icon('check')?> ذخیره تغییرات</button></form><?php service_gallery_form_section($service);?></details><?php else:?><article class="catalog-item catalog-item-readonly"><div><b><?=e($service['name'])?></b><span><?=e(service_category_label((string)$service['category']))?> · <?=e(pricing_type_label((string)$service['pricing_type']))?></span></div><strong><?=money($service['default_price'])?> تومان</strong><?=badge((int)$service['active']?'فعال':'غیرفعال',(int)$service['active']?'success':'neutral')?></article><?php endif;?><?php endforeach;endif;?></div></div></details>
        </div>
    </div><?php render_footer();
}

