                            <label class="check-line danger-line"><input type="checkbox" name="delete_image_ids[]" value="<?=$img['id']?>"><span>حذف از این خدمت</span></label>
                        </div>
                    </article>
                <?php endforeach;?>
            </div><?php else:?><div class="service-gallery-empty"><?=ui_icon('image')?><span>هنوز تصویری برای این خدمت یا گشت ثبت نشده است.</span></div><?php endif;?>

