                    <div class="service-media-library-body">
                    <?php $available=0;foreach($library as $asset)if(!isset($assigned[(int)$asset['id']]))$available++;if($available===0):?><p class="quiet">تصویر دیگری در کتابخانه برای انتخاب وجود ندارد.</p><?php else:?><div class="service-media-library-grid">
                        <?php foreach($library as $asset):$mid=(int)$asset['id'];if(isset($assigned[$mid]))continue;$usage=(int)($asset['usage_count']??0);$roomUsage=(int)($asset['room_usage_count']??0);$serviceUsage=(int)($asset['service_usage_count']??0);$display=media_display_path($asset,640);$name=trim((string)($asset['original_name']??''))?:'تصویر آپلودشده';if($usage===0)$deletable[$mid]=$name;$usageParts=[];if($roomUsage)$usageParts[]=fa_digits($roomUsage).' اتاق';if($serviceUsage)$usageParts[]=fa_digits($serviceUsage).' خدمت';$usageLabel=$usageParts?implode(' · ',$usageParts):'بدون استفاده';?>
