function page_waitlist(): void
{
    if(!feature_enabled('waitlist')){render_utility_status_page(404,'این قابلیت در حال حاضر فعال نیست','این بخش برای مجموعه فعلی خاموش است یا از تنظیمات غیرفعال شده است.',['tone'=>'info','label'=>'قابلیت غیرفعال','primary'=>['label'=>'بازگشت به پنل','href'=>runtime_base_url('index.php')]]);}
    $rows=db()->query("SELECT * FROM ".table('waitlist')." WHERE status='open' ORDER BY check_in,created_at")->fetchAll();$today=sokna_today();$readyCount=0;$staleCount=0;
    foreach($rows as $index=>$row){$stale=(string)$row['check_out']<=$today;$free=$stale?[]:free_rooms((string)$row['check_in'],(string)$row['check_out']);$capacity=0;foreach($free as $room)$capacity+=max(0,(int)($room['max_capacity']??0));$ready=!$stale&&$capacity>=(int)$row['guests_count'];$rows[$index]['_stale']=$stale;$rows[$index]['_free_rooms']=count($free);$rows[$index]['_free_capacity']=$capacity;$rows[$index]['_ready']=$ready;if($ready)$readyCount++;if($stale)$staleCount++;}
    usort($rows,static function(array $a,array $b): int{$rank=static fn(array $r)=>(!empty($r['_ready'])?0:(!empty($r['_stale'])?2:1));$ra=$rank($a);$rb=$rank($b);return $ra===$rb?strcmp((string)$a['check_in'],(string)$b['check_in']):$ra<=>$rb;});
    $openCreate=!empty($_GET['create'])||!$rows;
    render_header('لیست انتظار','waitlist');page_header('لیست انتظار','درخواست‌های بدون ظرفیت را پیگیری کنید؛ مواردی که دوباره ظرفیت پیدا کرده‌اند در اولویت قرار می‌گیرند.');
    ?><div class="waitlist-v2-workspace">
        <section class="waitlist-summary-strip" aria-label="خلاصه لیست انتظار"><span class="ready"><b><?=fa_digits($readyCount)?></b><small>قابل بررسی برای رزرو</small></span><span><b><?=fa_digits(max(0,count($rows)-$readyCount-$staleCount))?></b><small>هنوز در انتظار ظرفیت</small></span><span class="<?=$staleCount?'stale':''?>"><b><?=fa_digits($staleCount)?></b><small>تاریخ‌گذشته</small></span></section>
        <section class="panel waitlist-list-panel"><header class="panel-head"><div><h2>درخواست‌های باز</h2><p>درخواست‌های دارای ظرفیت قابل بررسی، بالاتر از بقیه نمایش داده می‌شوند.</p></div><?=badge(fa_digits(count($rows)).' باز',count($rows)?'warning':'neutral')?></header><div class="waitlist-request-list"><?php if(!$rows):?><div class="compact-empty"><b>درخواست بازی برای پیگیری نیست</b><span>اگر مهمانی برای تاریخ پر تماس گرفت، درخواست او را ثبت کنید تا بعداً دوباره ظرفیتش بررسی شود.</span></div><?php else:foreach($rows as $r):$phone=normalize_phone((string)($r['phone_normalized']??''));$state=!empty($r['_ready'])?'ready':(!empty($r['_stale'])?'stale':'waiting');?><article class="waitlist-request-card <?=$state?>" data-waitlist-state="<?=$state?>"><div class="waitlist-request-main"><header class="waitlist-request-head"><div><b><?=e($r['guest_name'])?></b><?php if($state==='ready'):?><?=badge('ظرفیت برای بررسی پیدا شده','success')?><?php elseif($state==='stale'):?><?=badge('تاریخ گذشته','danger')?><?php else:?><?=status_badge('در انتظار ظرفیت','waitlist')?><?php endif;?></div><span><?=jalali_date($r['check_in'])?> تا <?=jalali_date($r['check_out'])?> · <?=fa_digits($r['guests_count'])?> مهمان</span></header><div class="waitlist-capacity-signal <?=$state?>"><?php if($state==='ready'):?><b><?=ui_icon('check')?> امکان بررسی رزرو وجود دارد</b><span><?=fa_digits((int)$r['_free_rooms'])?> اتاق آزاد · مجموع ظرفیت فعلی تا <?=fa_digits((int)$r['_free_capacity'])?> نفر</span><?php elseif($state==='stale'):?><b><?=ui_icon('warning')?> بازه درخواستی گذشته است</b><span>در صورت نیاز با مهمان تماس بگیرید و این درخواست را تعیین تکلیف کنید.</span><?php else:?><b>هنوز ظرفیت کافی باز نشده است</b><span><?=fa_digits((int)$r['_free_rooms'])?> اتاق آزاد · مجموع ظرفیت فعلی تا <?=fa_digits((int)$r['_free_capacity'])?> نفر</span><?php endif;?></div><?php if($phone||!empty($r['notes'])):?><div class="waitlist-request-meta"><?php if($phone):?><a href="<?=e((string)tel_url($phone))?>"><?=ui_icon('phone')?> <bdi dir="ltr"><?=e(fa_digits(local_phone($phone)))?></bdi></a><?php endif;?><?php if(!empty($r['notes'])):?><span><?=ui_icon('info')?> <?=e((string)$r['notes'])?></span><?php endif;?></div><?php endif;?></div><div class="waitlist-request-actions"><?php if($state==='ready'):?><a class="btn primary" href="<?=e(url('reservation_new',['waitlist_id'=>$r['id']]))?>"><?=ui_icon('plus')?> بررسی و ساخت رزرو</a><?php endif;?><?php if($phone):?><a class="btn ghost" href="<?=e((string)whatsapp_url($phone))?>" target="_blank" rel="noopener"><?=ui_icon('whatsapp')?> واتس‌اپ</a><?php endif;?><form method="post" action="<?=e(url('waitlist_close'))?>" data-confirm="این درخواست از لیست انتظار بسته شود؟"><?=csrf_field()?><input type="hidden" name="waitlist_id" value="<?=$r['id']?>"><button class="btn ghost" type="submit">بستن</button></form></div></article><?php endforeach;endif;?></div></section>
        <details class="panel waitlist-create-panel" id="waitlist-create" <?=$openCreate?'open':''?>><summary class="disclosure-summary"><span><b><?=ui_icon('plus')?> درخواست جدید</b><small>وقتی تاریخ موردنظر مهمان فعلاً ظرفیت مناسب ندارد</small></span><span class="disclosure-meta">ثبت دستی</span></summary><div class="waitlist-create-body"><form method="post" action="<?=e(url('waitlist_add'))?>" class="form-grid waitlist-create-form"><?=csrf_field()?><label class="field"><span>نام مهمان *</span><input name="guest_name" required autocomplete="name"></label><label class="field"><span>تلفن</span><input name="phone" data-mobile-input dir="ltr" inputmode="tel" autocomplete="tel" maxlength="14" placeholder="09xxxxxxxxx"></label><label class="field"><span>ورود *</span><input class="jalali-date" readonly name="check_in" required></label><label class="field"><span>خروج *</span><input class="jalali-date" readonly name="check_out" required></label><?php number_stepper_field('guests_count','تعداد مهمان',2,1,29);?><label class="field full"><span>یادداشت</span><textarea name="notes" rows="3" placeholder="مثلاً ترجیح اتاق یا بهترین زمان تماس"></textarea></label><button class="btn primary full" type="submit"><?=ui_icon('plus')?> ثبت در لیست انتظار</button></form></div></details>
    </div><?php render_footer();
}


function page_messages(): void
{
    if(!feature_enabled('message_templates')){render_utility_status_page(404,'این قابلیت در حال حاضر فعال نیست','این بخش برای مجموعه فعلی خاموش است یا از تنظیمات غیرفعال شده است.',['tone'=>'info','label'=>'قابلیت غیرفعال','primary'=>['label'=>'بازگشت به پنل','href'=>runtime_base_url('index.php')]]);}
    $templates=db()->query('SELECT * FROM '.table('message_templates').' ORDER BY id')->fetchAll();$variables=template_allowed_variables();
    $groups=[
        'booking'=>['title'=>'درخواست و قطعی‌شدن','hint'=>'از پیشنهاد اولیه تا تأیید و پیگیری پرداخت.','keys'=>['reservation_offer','voucher_confirmation','deposit_request','balance_reminder']],
        'arrival'=>['title'=>'پیش از ورود','hint'=>'اطلاعات لازم برای نزدیک‌شدن به روز ورود.','keys'=>['pre_arrival']],
        'stay'=>['title'=>'حین اقامت','hint'=>'پیام کوتاه خوشامد و ارتباط در طول اقامت.','keys'=>['welcome']],
        'closing'=>['title'=>'پایان یا لغو','hint'=>'پایان اقامت و وضعیت‌های بسته‌شدن رزرو.','keys'=>['checkout_thanks','reservation_cancelled']],
    ];
    $usage=[
        'reservation_offer'=>'برای رزرو در حالت انتظار/پیشنهاد قبل از قطعی‌شدن.',
        'voucher_confirmation'=>'برای رزرو قطعی و ارسال خلاصه اقامت.',
        'deposit_request'=>'وقتی برای قطعی‌شدن یا ادامه رزرو نیاز به پرداخت است.',
        'balance_reminder'=>'وقتی رزرو مانده قابل پرداخت دارد.',
        'pre_arrival'=>'برای رزرو قطعی نزدیک به روز ورود.',
        'welcome'=>'در زمان حضور مهمان در اقامتگاه.',
        'checkout_thanks'=>'بعد از پایان اقامت.',
        'reservation_cancelled'=>'بعد از لغو رزرو.',
    ];
    $byKey=[];foreach($templates as $template)$byKey[(string)$template['template_key']]=$template;
    $known=[];foreach($groups as $group)foreach($group['keys'] as $key)$known[$key]=true;$other=[];foreach(array_keys($byKey) as $key)if(!isset($known[$key]))$other[]=$key;if($other)$groups['other']=['title'=>'سایر متن‌ها','hint'=>'متن‌های جدید یا سفارشی که در جریان‌های اصلی دسته‌بندی نشده‌اند.','keys'=>$other];
    $activeCount=count(array_filter($templates,static fn(array $t)=>(int)($t['active']??0)===1));
    $sample=['property_name'=>(string)setting('property_name','سکنا'),'property_address'=>(string)setting('property_address','نشانی مجموعه'),'property_phone'=>fa_digits(local_phone((string)setting('property_phone',''))),'reservation_code'=>'۰۵-۰۶-۰۰۲۸','reservation_status'=>'قطعی','guest_name'=>'مریم احمدی','phone'=>'۰۹۱۷۰۰۰۰۰۰۰','rooms_summary'=>'اتاق سیف','stay_summary'=>"اتاق سیف — ۱۸ تا ۲۲ مهر — ۴ شب",'check_in_date'=>'۱۸ مهر','check_out_date'=>'۲۲ مهر','room_nights'=>'۴','guest_count'=>'۲','reservation_amount_before_discount'=>'۱۲٬۰۰۰٬۰۰۰','discount_amount'=>'۰','reservation_amount_after_discount'=>'۱۲٬۰۰۰٬۰۰۰','additional_amount'=>'۱٬۰۰۰٬۰۰۰','services_amount'=>'۱٬۰۰۰٬۰۰۰','cafe_amount'=>'۰','total_amount'=>'۱۳٬۰۰۰٬۰۰۰','paid_amount'=>'۸٬۰۰۰٬۰۰۰','remaining_amount'=>'۵٬۰۰۰٬۰۰۰','check_in_time'=>(string)setting('check_in_time','۱۴:۰۰'),'check_out_time'=>(string)setting('check_out_time','۱۲:۰۰'),'services_summary'=>'گشت محلی','site_url'=>(string)setting('site_url',''),'issue_date'=>jalali_date(sokna_today()),'issue_time'=>fa_digits(date('H:i')),'issued_by'=>(string)(current_user()['display_name']??'مدیر'),'voucher_footer'=>(string)setting('voucher_footer','')];
    render_header('متن‌ها و پیام‌ها','messages');
    page_header('متن‌ها و پیام‌ها','متن‌های آماده را بر اساس مرحله سفر مهمان نگهداری کنید؛ ارسال واقعی همچنان از پرونده رزرو یا مهمان انجام می‌شود.');
    system_secondary_nav('messages');
    ?><section class="messages-v2-workspace">
        <div class="messages-summary" aria-label="خلاصه پیام‌های آماده"><span><b><?=fa_digits($activeCount)?></b><small>متن فعال</small></span><span><b><?=fa_digits(count($templates))?></b><small>کل متن‌ها</small></span></div>
        <details class="panel inline-form template-variables"><summary class="disclosure-summary"><span><b>متغیرهای قابل استفاده</b><small>برای شخصی‌سازی خودکار متن با اطلاعات رزرو</small></span><span class="disclosure-meta"><?=fa_digits(count($variables))?> متغیر</span></summary><div class="template-variable-list"><?php foreach($variables as $variable):?><code dir="ltr">{{<?=e($variable)?>}}</code><?php endforeach;?></div></details>
        <form method="post" action="<?=e(url('messages_save'))?>" class="message-templates-form"><?=csrf_field()?>
            <div class="message-stage-list"><?php foreach($groups as $groupKey=>$group):$groupItems=[];foreach($group['keys'] as $key)if(isset($byKey[$key]))$groupItems[]=$byKey[$key];if(!$groupItems)continue;?><section class="panel message-stage" data-message-stage="<?=e($groupKey)?>"><header class="panel-head"><div><h2><?=e($group['title'])?></h2><p><?=e($group['hint'])?></p></div><span class="badge neutral"><?=fa_digits(count($groupItems))?> متن</span></header><div class="message-template-list"><?php foreach($groupItems as $t):$key=(string)$t['template_key'];$preview=render_template_text((string)$t['body'],$sample);?><details class="message-template-item" data-template-key="<?=e($key)?>"><summary class="disclosure-summary"><span class="message-template-title"><b><?=e($t['title'])?></b><small><?=e($usage[$key]??'متن آماده مهمان')?></small></span><span class="disclosure-meta"><?=badge((int)$t['active']?'فعال':'غیرفعال',(int)$t['active']?'success':'neutral')?></span></summary><div class="message-template-editor"><div class="message-template-usage"><b>زمان استفاده</b><span><?=e($usage[$key]??'از داخل پرونده رزرو یا مهمان')?></span></div><div class="template-head"><label class="field"><span>عنوان داخلی</span><input name="templates[<?=$t['id']?>][title]" value="<?=e($t['title'])?>" required></label><label class="check-line message-template-toggle"><input type="checkbox" name="templates[<?=$t['id']?>][active]" value="1" <?=(int)$t['active']?'checked':''?>><span><b>فعال</b><small>در پیشنهادهای مناسب این مرحله نمایش داده شود.</small></span></label></div><label class="field"><span>متن پیام</span><textarea name="templates[<?=$t['id']?>][body]" rows="6" required><?=e($t['body'])?></textarea></label><section class="message-template-preview" aria-label="پیش‌نمایش متن"><header><b>پیش‌نمایش با داده نمونه</b><small>متغیرها فقط برای نمایش این نمونه جایگزین شده‌اند.</small></header><pre><?=e($preview)?></pre></section></div></details><?php endforeach;?></div></section><?php endforeach;?></div>
            <div class="form-actions template-save-actions"><button class="btn primary" type="submit"><?=ui_icon('check')?> ذخیره متن‌های آماده</button></div>
        </form>
    </section><?php render_footer();
}
