function page_users(): void
{
    $users=db()->query('SELECT * FROM '.table('users').' ORDER BY active DESC,role="admin" DESC,display_name,id')->fetchAll();
    $activeCount=count(array_filter($users,fn($user)=>(int)($user['active']??0)===1));
    $adminCount=count(array_filter($users,fn($user)=>(int)($user['active']??0)===1&&($user['role']??'')==='admin'));
    $currentId=(int)(current_user()['id']??0);
    render_header('کاربران و دسترسی‌ها','users');
    page_header('کاربران و دسترسی‌ها','حساب‌های ورود تیم را ببینید و فقط دسترسی لازم برای هر نقش را نگه دارید.');
    system_secondary_nav('users');
