                <div class="user-account-state"><?=badge(role_label((string)$u['role']),$u['role']==='admin'?'brand':($u['role']==='reservation'?'info':'neutral'))?><?=badge((int)$u['active']?'فعال':'غیرفعال',(int)$u['active']?'success':'neutral')?></div>
