function page_health(): void
{
    $h=health_snapshot();
    $critical=!$h['database']||!$h['storage'];
    $fontReady=!empty($h['font']['ready']);
    $actionCount=0;
    if(!$h['database'])$actionCount++;
    if(!$h['storage'])$actionCount++;
    if($h['maintenance'])$actionCount++;
    if(!$fontReady)$actionCount++;
    if(!empty($h['audit_warning']))$actionCount++;
    $warning=!$critical&&$actionCount>0;
    $tone=$critical?'danger':($warning?'warning':'success');
    $headline=$critical?'کار روزانه ممکن است مختل باشد':($warning?'سامانه قابل استفاده است؛ چند مورد را بررسی کنید':'سامانه برای کار روزانه آماده است');
    $copy=$critical?'یکی از بخش‌های اصلی سامانه آماده نیست. موارد نیازمند اقدام را قبل از ادامه بررسی کنید.':($warning?'عملیات اصلی در دسترس است، اما بهتر است موارد زیر بررسی شوند.':'پایگاه داده و مسیرهای اصلی آماده‌اند و مورد تازه‌ای برای رسیدگی دیده نمی‌شود.');
    render_header('وضعیت سامانه','health');
    page_header('وضعیت سامانه','وضعیت عملیاتی را اول ببینید؛ اطلاعات فنی فقط هنگام عیب‌یابی لازم است.');system_secondary_nav('health');?>
    <section class="health-v2-workspace">
        <section class="system-overview health-v2-overview <?=e($tone)?>"><div><span class="health-v2-kicker">وضعیت عملیاتی</span><h2><?=e($headline)?></h2><p><?=e($copy)?></p><div class="health-v2-overview-meta"><?=badge($critical?'نیاز به رسیدگی فوری':($warning?fa_digits($actionCount).' مورد برای بررسی':'نیازی به اقدام نیست'),$tone)?><span>نسخه <?=tech_value($h['version'])?></span></div></div><?=ui_icon($critical?'warning':($warning?'info':'check'))?></section>

        <section class="panel health-v2-checks"><header class="panel-head"><div><h2>بررسی‌های اصلی</h2><p>مواردی که روی کار روزانه اقامتگاه اثر مستقیم دارند.</p></div></header><div class="health-v2-check-list">
            <article class="health-v2-check"><span class="health-v2-check-icon"><?=ui_icon('database')?></span><div><b>اطلاعات سامانه</b><small>ارتباط با پایگاه داده</small></div><?=badge($h['database']?'آماده':'خطا',$h['database']?'success':'danger')?></article>
            <article class="health-v2-check"><span class="health-v2-check-icon"><?=ui_icon('storage')?></span><div><b>ذخیره فایل‌ها</b><small>runtime، logs و uploads</small></div><?=badge($h['storage']?'آماده':'خطا',$h['storage']?'success':'danger')?></article>
            <article class="health-v2-check"><span class="health-v2-check-icon"><?=ui_icon('font')?></span><div><b>نمایش فارسی</b><small>فونت اصلی رابط</small></div><?=badge($fontReady?'آماده':'نیاز به بررسی',$fontReady?'success':'warning')?></article>
            <article class="health-v2-check"><span class="health-v2-check-icon"><?=ui_icon('update')?></span><div><b>وضعیت عملیات سامانه</b><small>حالت نگهداری یا به‌روزرسانی</small></div><?=badge($h['maintenance']?'در حال نگهداری':'عادی',$h['maintenance']?'warning':'success')?></article>
        </div></section>

        <?php if($actionCount>0):?><section class="health-v2-actions" aria-labelledby="health-actions-title"><div class="health-v2-section-head"><div><h2 id="health-actions-title">نیاز به اقدام</h2><p>فقط مواردی که الان یا به‌تازگی نیازمند توجه هستند.</p></div><?=badge(fa_digits($actionCount).' مورد',$critical?'danger':'warning')?></div>
            <?php if(!$h['database']):?><section class="panel health-v2-action danger"><header class="panel-head"><div><h3>پایگاه داده در دسترس نیست</h3><p>ثبت و خواندن اطلاعات ممکن است مختل باشد. قبل از عملیات نوشتنی، اتصال دیتابیس Host را بررسی کنید.</p></div><?=badge('خطا','danger')?></header></section><?php endif;?>
            <?php if(!$h['storage']):?><section class="panel health-v2-action danger"><header class="panel-head"><div><h3>یکی از مسیرهای ذخیره آماده نیست</h3><p>Upload، Log یا فایل‌های Runtime ممکن است درست نوشته نشوند. جزئیات مسیرها پایین صفحه قابل بررسی است.</p></div><?=badge('خطا','danger')?></header></section><?php endif;?>
