function page_updates(): void
{
    $updates=[];$runtimeWarning=null;
    try{$updates=db()->query('SELECT * FROM '.table('system_updates').' ORDER BY created_at DESC LIMIT 20')->fetchAll();}catch(Throwable $e){log_exception($e,'updates_history');$runtimeWarning='تاریخچه به‌روزرسانی فعلاً قابل خواندن نیست.';}
    $requested=trim((string)($_GET['operation']??''));$active=null;$status=null;$previous=null;
    try{$active=UpdateManagerV2::activeOperation();$previous=UpdateManagerV2::previousRollbackCandidate();}catch(Throwable $e){log_exception($e,'updates_active_operation');$runtimeWarning='وضعیت به‌روزرسانی فعلاً قابل خواندن نیست.';}
    if($requested!==''){try{$status=UpdateManagerV2::status($requested);}catch(Throwable $e){log_exception($e,'updates_requested_operation');$runtimeWarning='عملیات انتخاب‌شده پیدا نشد.';}}
    if(!$status&&$active)$status=$active;
    $current=UpdateManagerV2::currentVersion();
    $phaseLabels=['files'=>'جایگزینی فایل‌ها','delete'=>'پاک‌سازی فایل‌های قدیمی','migration'=>'به‌روزرسانی ساختار داده','health'=>'بررسی سلامت نسخه جدید','finish'=>'پایان نصب','rollback_sql'=>'آماده‌سازی بازگشت','rollback_files'=>'بازگردانی فایل‌ها','rollback_database'=>'بازگردانی اطلاعات','source_health'=>'بررسی نسخه بازیابی‌شده','done'=>'کامل'];
    render_header('به‌روزرسانی سامانه','updates');page_header('به‌روزرسانی سامانه','نصب نسخه جدید و بازیابی اضطراری را با وضعیت روشن و قابل پیگیری انجام دهید.');system_secondary_nav('updates');?>
    <section class="updates-v2-workspace">
        <?php if($runtimeWarning):?><div class="inline-alert warning"><?=e($runtimeWarning)?></div><?php endif;?>
        <?php if($status&&!in_array($status['state'],['success','rolled_back'],true)):$terminal=$status['state']==='rollback_failed';$rollingBack=in_array($status['state'],['rollback','rollback_failed'],true);?>
