            <section class="panel stack update-runner updates-v2-runner" data-update-runner data-operation="<?=e($status['operation'])?>" data-action="<?=e(url('update_continue'))?>" data-csrf="<?=e(csrf_token())?>" data-state="<?=e($status['state'])?>"><header class="panel-head"><div><h2>پیشرفت عملیات</h2><p data-update-message><?=e($status['message'])?></p></div><?=badge(fa_digits((string)$status['progress']).'٪',$terminal?'danger':'warning')?></header><progress class="update-progress" max="100" value="<?=$status['progress']?>" data-update-progress aria-label="پیشرفت به‌روزرسانی" aria-valuemin="0" aria-valuemax="100" aria-valuenow="<?=$status['progress']?>"><?=$status['progress']?>%</progress><div class="update-meta"><span><?=e($phaseLabels[(string)$status['phase']]??'در حال پردازش')?></span><span data-update-state><?=$terminal?'نیاز به تلاش دوباره':'ادامه خودکار فعال است'?></span></div><?php if($status['last_error']):?><div class="inline-alert warning"><b>مرحله ناموفق</b><span><?=e((string)$status['last_error']['message'])?><?php if(!empty($status['last_error']['detail'])):?><small><?=e((string)$status['last_error']['detail'])?></small><?php endif;?></span></div><?php endif;?><div class="form-actions"><button class="btn primary" type="button" data-update-manual <?=$terminal?'':'hidden'?>><?=ui_icon('update')?> تلاش دوباره برای بازیابی</button><?php if($status['state']==='running'):?><form method="post" action="<?=e(url('update_recover'))?>" data-confirm="نصب متوقف شود و Snapshot قبلی بازیابی شود؟"><?=csrf_field()?><input type="hidden" name="operation" value="<?=e($status['operation'])?>"><button class="btn danger ghost" type="submit"><?=ui_icon('warning')?> توقف و بازیابی</button></form><?php endif;?></div></section>
            <div class="inline-alert info"><b>صفحه را باز نگه دارید.</b><span>اجرای مرحله‌ای ادامه پیدا می‌کند. اگر ارتباط مرورگر قطع شود، وضعیت عملیات در Journal حفظ می‌شود و می‌توان از همین صفحه ادامه داد.</span></div>
        <?php else:?>
            <section class="system-overview updates-v2-overview success"><div><span class="updates-v2-kicker">وضعیت نسخه</span><h2>سامانه آماده دریافت بسته جدید است</h2><p>عملیات Update ناتمامی دیده نمی‌شود. فقط بسته رسمی ساخته‌شده برای نسخه نصب‌شده را انتخاب کنید.</p><div class="updates-v2-overview-meta"><?=badge('نسخه فعلی','success')?><span><?=tech_value($current)?></span></div></div><?=ui_icon('check')?></section>
            <section class="panel updates-v2-install"><header class="panel-head"><div><h2>نصب بسته رسمی</h2><p>پیش از جایگزینی فایل‌ها، بسته بررسی و Snapshot داخلی بازیابی ساخته می‌شود.</p></div><?=badge('نیازمند تأیید رمز','info')?></header><ol class="updates-v2-checklist"><li><b>بسته باید دقیقاً برای نسخه <?=e($current)?> ساخته شده باشد.</b><span>Updater نسخه مبدا، Hash فایل‌ها و ساختار بسته را قبل از اجرا بررسی می‌کند.</span></li><li><b>برای تغییر مهم، یک پشتیبان مستقل هم نگه دارید.</b><span>Updater Snapshot داخلی دارد، اما Backup مستقل مسیر Recovery جداگانه‌ای به شما می‌دهد.</span></li><li><b>در زمان Update، حالت نگهداری فعال می‌شود.</b><span>پس از نصب، نسخه، دیتابیس، Schema و Storage دوباره Health Check می‌شوند.</span></li></ol><div class="updates-v2-preflight-actions"><a class="btn" href="<?=e(url('backup'))?>"><?=ui_icon('backup')?> رفتن به پشتیبان</a></div><form method="post" action="<?=e(url('update_upload'))?>" enctype="multipart/form-data" class="update-upload updates-v2-upload file-action-form"><?=csrf_field()?><?php file_input_field('update_package','فایل Update رسمی','.zip,application/zip','فقط ZIP رسمی مخصوص نسخه نصب‌شده؛ حداکثر ۱۵۰ مگابایت.',true,'انتخاب فایل Update')?><button class="btn primary" type="submit"><?=ui_icon('update')?> بررسی و شروع نصب</button></form></section>
            <div class="inline-alert info"><b>حفاظت از اطلاعات پس از به‌روزرسانی</b><span>پس از نصب موفق، بازگشت خودکار به Snapshot قبلی غیرفعال است تا رزروها و پرداخت‌های جدید بازنویسی نشوند. در صورت نیاز به بازیابی، ابتدا پشتیبان تازه تهیه و وضعیت داده‌ها در محیط آزمایشی بررسی شود.</span></div>
            <?php if($previous):?><details class="panel danger-zone updates-v2-rollback"><summary class="disclosure-summary"><span><b><?=ui_icon('warning')?> بازگشت اضطراری به نسخه <?=e((string)$previous['from'])?></b><small>فقط وقتی نسخه فعلی مشکل جدی دارد و Snapshot بازیابی هنوز معتبر است.</small></span><span class="disclosure-meta">عملیات حساس</span></summary><div class="updates-v2-rollback-body"><div class="inline-alert warning"><b>بازگشت، فقط فایل‌ها را Undo نمی‌کند.</b><span>پایگاه داده نیز به Snapshot قبل از Update برمی‌گردد؛ رزروها، پرداخت‌ها و تغییرات ثبت‌شده بعد از آن نقطه ممکن است از بین بروند.</span></div><form method="post" action="<?=e(url('update_rollback_previous'))?>" class="stack" data-confirm="نسخه و اطلاعات به Snapshot قبل از Update برگردد؟"><?=csrf_field()?><label class="check-line updates-v2-rollback-ack"><input type="checkbox" name="rollback_ack" value="1" required><span><b>می‌دانم داده‌های بعد از Snapshot ممکن است از بین بروند.</b><small>در صورت امکان قبل از ادامه یک پشتیبان تازه بگیرید.</small></span></label><button class="btn danger" type="submit"><?=ui_icon('warning')?> شروع بازگشت اضطراری</button></form></div></details><?php endif;?>
        <?php endif;?>
