function page_voucher(): never
{
    $id=(int)($_GET['id']??0);$r=get_reservation($id);if(!$r){render_utility_status_page(404,'رزرو پیدا نشد','این رزرو وجود ندارد یا دیگر از مسیر فعلی قابل دسترسی نیست.',['tone'=>'info','label'=>'رزرو پیدا نشد','primary'=>['label'=>'بازگشت به رزروها','href'=>url('calendar')]]);}
    $mode=(string)($_GET['mode']??'a5');$mode=$mode==='receipt'?'receipt':'a5';$voucherBodyClass=$mode==='receipt'?'voucher-receipt':'voucher-a5';
    $a=get_allocations($id);$services=get_services($id);$cafe=get_cafe_charges($id);$ledger=LedgerService::summary($id);
    $logoUrl=property_logo_url()??system_brand_logo_url(true);$stamp=(string)setting('voucher_stamp_path','');$configuredTitle=trim((string)setting('voucher_title','تأییدیه رزرو'))?:'تأییدیه رزرو';
    $property=(string)setting('property_name','سکنا');$propertyPhone=local_phone((string)setting('property_phone',''));$propertyAddress=trim((string)setting('property_address',''));$whatsapp=local_phone((string)setting('whatsapp_number',''));
    [$checkIn,$checkOut]=reservation_date_bounds($a);
    $activeServices=array_values(array_filter($services,fn($s)=>(string)($s['status']??'')!=='cancelled'));
