function public_capacity_calendar_view(string $today,string $horizon,array $capacity,int $guests=2): void
{
    $todayDt=new DateTimeImmutable($today);$endDt=new DateTimeImmutable($horizon);
    $startJ=Jalali::toJalali((int)$todayDt->format('Y'),(int)$todayDt->format('n'),(int)$todayDt->format('j'));
    $endJ=Jalali::toJalali((int)$endDt->format('Y'),(int)$endDt->format('n'),(int)$endDt->format('j'));
    $startSerial=$startJ['jy']*12+$startJ['jm']-1;$endSerial=$endJ['jy']*12+$endJ['jm']-1;
    $monthNames=[1=>'فروردین',2=>'اردیبهشت',3=>'خرداد',4=>'تیر',5=>'مرداد',6=>'شهریور',7=>'مهر',8=>'آبان',9=>'آذر',10=>'دی',11=>'بهمن',12=>'اسفند'];
    $week=['ش','ی','د','س','چ','پ','ج'];$monthIndex=0;
    ?><section class="public-flex-calendar" aria-labelledby="publicCapacityCalendarTitle" data-public-calendar>
        <header class="public-flex-calendar-head"><h2 id="publicCapacityCalendarTitle">کدام شب‌ها اتاق خالی داریم؟</h2><p>روزهای دارای ظرفیت روی تقویم مشخص‌اند. یک روز را انتخاب کنید تا ادامه بررسی اقامت از همان تاریخ انجام شود.</p></header>
        <div class="public-month-toolbar"><button type="button" class="public-month-nav" data-public-month-prev aria-label="ماه قبل"><?=ui_icon('chevron-right')?></button><b data-public-month-title></b><button type="button" class="public-month-nav" data-public-month-next aria-label="ماه بعد"><?=ui_icon('chevron-left')?></button></div>
        <div class="public-capacity-months" data-public-months><?php for($serial=$startSerial;$serial<=$endSerial;$serial++):$jy=intdiv($serial,12);$jm=$serial%12+1;$g=Jalali::toGregorian($jy,$jm,1);$firstIso=sprintf('%04d-%02d-%02d',$g['gy'],$g['gm'],$g['gd']);$offset=((int)(new DateTimeImmutable($firstIso))->format('w')+1)%7;$days=Jalali::monthLength($jy,$jm);$monthLabel=$monthNames[$jm].' '.fa_digits($jy);$openNights=0;$limitedNights=0;$offeredNights=0;for($summaryDay=1;$summaryDay<=$days;$summaryDay++){$sg=Jalali::toGregorian($jy,$jm,$summaryDay);$summaryIso=sprintf('%04d-%02d-%02d',$sg['gy'],$sg['gm'],$sg['gd']);if($summaryIso<$today||$summaryIso>=$horizon)continue;$summaryCapacity=$capacity[$summaryIso]??null;$summaryState=(string)($summaryCapacity['status']??'unavailable');if($summaryState!=='unavailable')$offeredNights++;if($summaryState==='available')$openNights++;elseif($summaryState==='limited'){$openNights++;$limitedNights++;}}?>
            <article class="public-capacity-month <?=$monthIndex===0?'is-active':''?>" data-public-month-index="<?=$monthIndex?>" data-public-month-label="<?=e($monthLabel)?>">
                <div class="public-month-summary <?=$openNights===0?'is-full':''?>"><?php if($openNights>0):?><b><?=fa_digits($openNights)?> شب با ظرفیت در این ماه</b><span><?=$limitedNights>0?fa_digits($limitedNights).' شب ظرفیت محدود دارد.':'روزهای سبز ظرفیت مناسب دارند.'?></span><?php elseif($offeredNights>0):?><b>در این ماه فعلاً شب خالی نداریم</b><span>ماه بعد را هم بررسی کنید.</span><?php else:?><b>برای این ماه ظرفیت عمومی تعریف نشده</b><span>برای راهنمایی می‌توانید با پذیرش تماس بگیرید.</span><?php endif;?></div>
                <div class="public-capacity-week" aria-hidden="true"><?php foreach($week as $dayName):?><span><?=$dayName?></span><?php endforeach;?></div>
                <div class="public-capacity-days" role="grid" aria-label="<?=e($monthLabel)?>"><?php for($i=0;$i<$offset;$i++):?><span class="public-capacity-blank" aria-hidden="true"></span><?php endfor;?><?php for($jd=1;$jd<=$days;$jd++):$gd=Jalali::toGregorian($jy,$jm,$jd);$iso=sprintf('%04d-%02d-%02d',$gd['gy'],$gd['gm'],$gd['gd']);if($iso>$horizon):?><span class="public-capacity-blank" aria-hidden="true"></span><?php continue;endif;$isPast=$iso<$today;$isToday=$iso===$today;$isBoundary=$iso===$horizon;$dayCapacity=$capacity[$iso]??null;$state=$isPast?'past':($isBoundary?'boundary':(string)($dayCapacity['status']??'unavailable'));$available=(int)($dayCapacity['available']??0);$friday=(new DateTimeImmutable($iso))->format('w')==='5';$dateText=fa_digits($jd).' '.$monthNames[$jm];$jalali=sprintf('%04d/%02d/%02d',$jy,$jm,$jd);?>
                    <?php if($isPast):?><span class="public-capacity-day <?=$isToday?'is-today ':''?><?=$friday?'is-friday':''?>" data-capacity-state="past" role="gridcell" aria-label="<?=e($dateText)?>، گذشته"><b><?=fa_digits($jd)?></b></span>
                    <?php elseif($isBoundary):?><span class="public-capacity-day <?=$friday?'is-friday':''?>" data-capacity-state="boundary" role="gridcell" aria-label="<?=e($dateText)?>، فقط برای تاریخ خروج"><b><?=fa_digits($jd)?></b><small>فقط خروج</small></span>
                    <?php elseif($state==='unavailable'):?><span class="public-capacity-day <?=$isToday?'is-today ':''?><?=$friday?'is-friday':''?>" data-capacity-state="unavailable" role="gridcell" aria-label="<?=e($dateText)?>، خارج از عرضه عمومی"><b><?=fa_digits($jd)?></b></span>
                    <?php elseif($state==='full'):?><span class="public-capacity-day <?=$isToday?'is-today ':''?><?=$friday?'is-friday':''?>" data-capacity-state="full" role="gridcell" aria-label="<?=e($dateText)?>، ظرفیت تکمیل"><b><?=fa_digits($jd)?></b></span>
                    <?php else:$href=external_url('public',['mode'=>'fixed','check_in'=>$iso,'guests'=>$guests]);?><a class="public-capacity-day <?=$isToday?'is-today ':''?><?=$friday?'is-friday':''?>" data-capacity-state="<?=e($state)?>" data-public-jalali="<?=e($jalali)?>" role="gridcell" href="<?=e($href)?>" aria-label="<?=e($dateText)?>، <?=fa_digits($available)?> اتاق آزاد"><b><?=fa_digits($jd)?></b><small><?=fa_digits($available)?> اتاق</small></a><?php endif;?>
                <?php endfor;?></div>
            </article><?php $monthIndex++;endfor;?></div>
        <footer class="public-calendar-foot"><span><?=ui_icon('calendar')?> امکان شروع اقامت تا شب قبل از <?=jalali_date($horizon)?></span><small>آخرین تاریخ نمایش فقط می‌تواند تاریخ خروج باشد.</small></footer>
    </section><?php
}

function public_room_media(array $room,array $profile): void
{
    $images=(array)($profile['images']??[]);$cover=$images?media_display_path($images[0],1280):'';$count=count($images);
    ?><div class="public-room-media <?=$cover===''?'is-empty':''?>"><?php if($cover!==''):?><img src="<?=e(runtime_base_url($cover))?>" alt="تصویر اتاق <?=e((string)$room['name'])?>" loading="lazy"><?php else:?><div class="public-room-media-empty"><?=ui_icon('image')?><span>تصویر اتاق هنوز ثبت نشده</span></div><?php endif;?><?php if($count>1):?><span class="public-gallery-count"><?=ui_icon('image')?> <?=fa_digits($count)?> عکس</span><?php endif;?></div><?php
}

function public_room_facts(array $room,array $profile,int $assigned): void
{
    $amenities=(array)($profile['amenities']??[]);?><div class="public-room-facts"><span><?=ui_icon('guests')?> تا <?=fa_digits((int)$room['max_capacity'])?> مهمان</span><?php if(!empty($profile['enabled'])):?><span><?=ui_icon('bed')?> <?=e((string)$profile['bed_summary'])?></span><span><?=ui_icon('shower')?> <?=$profile['private_bathroom']?'سرویس اختصاصی':'سرویس مشترک'?></span><?php endif;?><?php foreach(array_slice($amenities,0,2) as $amenity):?><span><?=ui_icon(amenity_icon_name($amenity))?> <?=e((string)$amenity['name'])?></span><?php endforeach;?></div><?php
}

function page_public(): void
{
    if(!feature_enabled('public_capacity')){render_utility_status_page(404,'این قابلیت در حال حاضر فعال نیست','این بخش برای مجموعه فعلی خاموش است یا از تنظیمات غیرفعال شده است.',['tone'=>'info','label'=>'قابلیت غیرفعال','primary'=>['label'=>'بازگشت به پنل','href'=>runtime_base_url('index.php')]]);}
    $today=sokna_today();$maxDate=public_horizon_date();$checkIn=trim((string)($_GET['check_in']??''));$checkOut=trim((string)($_GET['check_out']??''));$mode=(string)($_GET['mode']??'fixed');if(!in_array($mode,['fixed','flex'],true))$mode='fixed';$guests=max(1,min(20,(int)en_digits((string)($_GET['guests']??2))));
    $toIso=static function(string $raw): ?string {if($raw==='')return null;if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$raw))return $raw;return Jalali::toIso(en_digits($raw));};
    $in=$toIso($checkIn);$out=$toIso($checkOut);$options=[];$alternatives=[];$searched=false;$invalid=false;$partial=false;
    if($checkIn!==''||$checkOut!==''){
        if($in&&$out){if($in<$today||$in>=$out||$out>$maxDate||$in>=(new DateTimeImmutable($maxDate))->format('Y-m-d'))$invalid=true;else{$searched=true;$options=public_find_stay_options($in,$out,$guests,3);if(!$options)$alternatives=public_nearby_alternatives($in,$out,$guests,5);}}
        elseif($in&&$in>=$today&&$in<$maxDate){$partial=true;}else{$invalid=true;}
    }
    $capacity=public_capacity_calendar($today,$maxDate);$property=(string)setting('property_name','سکنا');$wa=normalize_phone((string)setting('whatsapp_number',''));$phone=normalize_phone((string)setting('property_phone',''));$address=trim((string)setting('property_address',''));$propertyAmenities=property_amenities(true);$showPrices=setting('public_show_prices','1')==='1';$intro=public_copy('public_intro_text','تاریخ سفرتان را انتخاب کنید تا اتاق‌های مناسب و راه ارتباط با پذیرش را ببینید.');$heroImage='';foreach(get_current_rooms() as $heroRoom){if(empty($heroRoom['public_profile_enabled']))continue;$heroPath=room_cover_path((int)$heroRoom['id']);if($heroPath!==''){$heroImage=runtime_base_url($heroPath);break;}}$nights=($searched&&$in&&$out)?max(0,(int)(new DateTimeImmutable($in))->diff(new DateTimeImmutable($out))->days):0;$fallbackWa=null;$callUrl=$phone?tel_url($phone):null;$generalWa=$wa?whatsapp_url($wa,'سلام، برای بررسی ظرفیت اقامت پیام می‌دهم.'):null;$checkInMax=(new DateTimeImmutable($maxDate))->modify('-1 day')->format('Y-m-d');
    if($searched&&!$options&&$wa&&$in&&$out){$fallbackText='سلام، برای اقامت از '.jalali_date($in).' تا '.jalali_date($out).' برای '.fa_digits($guests).' نفر درخواست بررسی ظرفیت دارم. تاریخ من تا حدی انعطاف‌پذیر است و اگر بازه نزدیک دیگری خالی باشد لطفاً پیشنهاد بدهید.';$fallbackWa=whatsapp_url($wa,$fallbackText);}
    render_header('ظرفیت اقامت','public',true);
    ?><section class="public-capacity-v5" data-public-mode="<?=e($mode)?>">
        <header class="public-guest-header"><div class="public-guest-brand"><?=property_brand_mark(false)?><div><b><?=e($property)?></b><?php if($address!==''):?><span><?=ui_icon('location')?> <?=e($address)?></span><?php else:?><span>بررسی ظرفیت اقامت</span><?php endif;?></div></div><div class="public-guest-contact"><?php if($generalWa):?><a class="public-contact-action whatsapp" href="<?=e($generalWa)?>" target="_blank" rel="noopener" aria-label="گفت‌وگو با پذیرش در واتس‌اپ"><?=ui_icon('whatsapp')?><span>واتس‌اپ</span></a><?php endif;?><?php if($callUrl):?><a class="public-contact-action phone" href="<?=e((string)$callUrl)?>" aria-label="تماس با پذیرش"><?=ui_icon('phone')?><span>تماس</span></a><?php endif;?></div></header>

        <section class="public-guest-intro <?=$heroImage!==''?'has-media':''?>"><div class="public-intro-copy"><h1>اتاق مناسب برای سفرتان را پیدا کنید</h1><p><?=e($intro)?></p><nav class="public-intent-tabs" aria-label="روش بررسی ظرفیت"><a class="<?=$mode==='fixed'?'active':''?>" href="<?=e(external_url('public',['mode'=>'fixed','guests'=>$guests]))?>" <?=$mode==='fixed'?'aria-current="page"':''?>>تاریخ مشخص دارم</a><a class="<?=$mode==='flex'?'active':''?>" href="<?=e(external_url('public',['mode'=>'flex','guests'=>$guests]))?>" <?=$mode==='flex'?'aria-current="page"':''?>>تاریخم منعطف است</a></nav></div><div class="public-intro-media" aria-hidden="true"><?php if($heroImage!==''):?><img src="<?=e($heroImage)?>" alt="" fetchpriority="high"><?php else:?><div class="public-intro-media-empty"><?=property_brand_mark(false)?></div><?php endif;?></div></section>

        <?php if($mode==='fixed'):?><section class="public-fixed-flow">
            <form method="get" class="public-search-dock" aria-label="بررسی ظرفیت"><input type="hidden" name="page" value="public"><input type="hidden" name="mode" value="fixed"><label class="public-search-field"><span>ورود</span><input class="jalali-date" readonly name="check_in" data-min-iso="<?=e($today)?>" data-max-iso="<?=e($checkInMax)?>" value="<?=$in?jalali_date($in):''?>" placeholder="انتخاب تاریخ" required></label><label class="public-search-field"><span>خروج</span><input class="jalali-date" readonly name="check_out" data-min-iso="<?=e($today)?>" data-max-iso="<?=e($maxDate)?>" value="<?=$out?jalali_date($out):''?>" placeholder="انتخاب تاریخ" required></label><div class="public-search-guests"><span>مهمان</span><?php number_stepper_field('guests','',$guests,1,20);?></div><button class="public-search-submit" type="submit"><?=ui_icon('search')?> نمایش اتاق‌های خالی</button></form>
            <?php if($invalid):?><div class="public-system-note error"><?=ui_icon('warning')?><span>تاریخ ورود و خروج باید داخل بازه نمایش عمومی باشند و خروج بعد از ورود باشد.</span></div><?php elseif($partial):?><div class="public-system-note info"><?=ui_icon('info')?><span>تاریخ ورود انتخاب شد؛ تاریخ خروج را مشخص کنید تا ظرفیت بررسی شود.</span></div><?php endif;?>

            <?php if($searched&&$in&&$out):?><section class="public-stay-results"><header class="public-result-head"><div><h2><?=$options?fa_digits(count($options)).' گزینه مناسب برای '.fa_digits($guests).' مهمان':'برای این بازه گزینه مناسبی پیدا نشد'?></h2><p><?=jalali_date($in)?> تا <?=jalali_date($out)?> · <?=fa_digits($nights)?> شب</p></div></header>
                <?php if($options):?><div class="public-stay-grid"><?php foreach($options as $option):$roomNames=array_map(static fn(array $rr):string=>(string)$rr['name'],$option['rooms']);$isMulti=(int)$option['room_count']>1;$requestText='سلام، برای اقامت از '.jalali_date($in).' تا '.jalali_date($out).' برای '.fa_digits($guests).' نفر، گزینه «'.implode(' + ',$roomNames).'» را در صفحه ظرفیت دیدم و درخواست بررسی و هماهنگی دارم.';$requestWa=$wa?whatsapp_url($wa,$requestText):null;$lead=$option['rooms'][0];$leadProfile=room_public_profile($lead);?><article class="public-stay-card <?=$isMulti?'is-multi':''?>">
                    <?php if(!$isMulti):public_room_media($lead,$leadProfile);else:?><div class="public-multi-media"><?php foreach(array_slice($option['rooms'],0,3) as $rr):$pp=room_public_profile($rr);$imgs=$pp['images'];$src=$imgs?media_display_path($imgs[0],640):'';?><div><?php if($src!==''):?><img src="<?=e(runtime_base_url($src))?>" alt="<?=e((string)$rr['name'])?>" loading="lazy"><?php else:?><?=ui_icon('image')?><?php endif;?></div><?php endforeach;?></div><?php endif;?>
                    <div class="public-stay-card-body"><header class="public-stay-card-head"><div><span class="public-room-kicker"><?=$isMulti?'ترکیب '.fa_digits((int)$option['room_count']).' اتاق':'اتاق پیشنهادی'?></span><h3><?=e($isMulti?'اقامت در '.implode(' + ',$roomNames):(string)$lead['name'])?></h3></div><?php if($showPrices):?><div class="public-option-price"><b><?=money((int)$option['price'])?></b><span>تومان · قیمت پایه <?=fa_digits($nights)?> شب</span></div><?php endif;?></header>
                    <?php if(!$isMulti):public_room_facts($lead,$leadProfile,(int)$lead['assigned_guests']);else:?><div class="public-multi-rooms"><?php foreach($option['rooms'] as $rr):$pp=room_public_profile($rr);?><div><b><?=e((string)$rr['name'])?></b><span><?=fa_digits((int)$rr['assigned_guests'])?> مهمان<?php if($pp['enabled']):?> · <?=e((string)$pp['bed_summary'])?> · <?=$pp['private_bathroom']?'سرویس اختصاصی':'سرویس مشترک'?><?php endif;?></span></div><?php endforeach;?></div><?php endif;?>
                    <?php $allImages=[];foreach($option['rooms'] as $rr){foreach(room_images((int)$rr['id']) as $img)$allImages[]=['room'=>$rr,'img'=>$img];}if($allImages):?><details class="public-room-details"><summary><?=ui_icon('image')?> مشاهده <?=fa_digits(count($allImages))?> عکس و جزئیات</summary><div class="public-room-gallery-grid"><?php foreach(array_slice($allImages,0,8) as $entry):$src=media_display_path($entry['img'],640);if($src==='')continue;?><img src="<?=e(runtime_base_url($src))?>" alt="<?=e((string)$entry['room']['name'])?>" loading="lazy"><?php endforeach;?></div></details><?php endif;?>
                    <div class="public-card-actions"><?php if($requestWa):?><a class="public-primary-action whatsapp" href="<?=e($requestWa)?>" target="_blank" rel="noopener"><?=ui_icon('whatsapp')?> درخواست این گزینه در واتس‌اپ</a><?php elseif($callUrl):?><a class="public-primary-action phone" href="<?=e((string)$callUrl)?>"><?=ui_icon('phone')?> تماس برای این گزینه</a><?php endif;?><?php if($requestWa&&$callUrl):?><a class="public-secondary-action" href="<?=e((string)$callUrl)?>"><?=ui_icon('phone')?> تماس</a><?php endif;?></div></div></article><?php endforeach;?></div>
                <div class="public-system-note neutral"><?=ui_icon('info')?><span><b>ارسال درخواست به معنی رزرو قطعی نیست.</b> ظرفیت و مبلغ نهایی توسط پذیرش تأیید می‌شود.</span></div>
                <?php else:?><section class="public-no-availability"><div class="public-system-note warning"><?=ui_icon('calendar')?><span><b>این بازه برای <?=fa_digits($guests)?> مهمان ظرفیت مناسب ندارد.</b> اگر تاریخ انعطاف دارد، بازه‌های نزدیک را بررسی کنید.</span></div><?php if($alternatives):?><div class="nearby-list"><?php foreach($alternatives as $a):$offset=(int)($a['offset']??0);$when=$offset>0?fa_digits($offset).' روز دیرتر':fa_digits(abs($offset)).' روز زودتر';$href=external_url('public',['mode'=>'fixed','check_in'=>$a['check_in'],'check_out'=>$a['check_out'],'guests'=>$guests]);?><a href="<?=e($href)?>"><span><b><?=jalali_date($a['check_in'])?> تا <?=jalali_date($a['check_out'])?></b><small><?=e($when)?> · <?=fa_digits((int)($a['nights']??0))?> شب</small></span><?php if($showPrices):?><span>از <?=money((int)$a['from_price'])?> تومان</span><?php endif;?></a><?php endforeach;?></div><?php endif;?><div class="public-card-actions"><?php if($fallbackWa):?><a class="public-primary-action whatsapp" href="<?=e($fallbackWa)?>" target="_blank" rel="noopener"><?=ui_icon('whatsapp')?> درخواست بررسی تاریخ نزدیک</a><?php endif;?><?php if($callUrl):?><a class="public-secondary-action" href="<?=e((string)$callUrl)?>"><?=ui_icon('phone')?> تماس</a><?php endif;?></div></section><?php endif;?></section><?php endif;?>
        </section><?php else:?><section class="public-flex-flow"><?php public_capacity_calendar_view($today,$maxDate,$capacity,$guests);?></section><?php endif;?>

        <?php if($propertyAmenities):?><section class="public-property-preview"><header><span class="eyebrow">امکانات اقامتگاه</span><h2>امکانات اصلی مجموعه</h2></header><div class="public-property-amenity-grid"><?php foreach(array_slice($propertyAmenities,0,8) as $amenity):?><span><i><?=ui_icon(amenity_icon_name($amenity))?></i><b><?=e((string)$amenity['name'])?></b></span><?php endforeach;?></div><?php if(count($propertyAmenities)>8):?><details class="public-all-amenities"><summary>مشاهده همه امکانات <?=ui_icon('chevron-left')?></summary><div><?php foreach($propertyAmenities as $amenity):?><span><?=ui_icon(amenity_icon_name($amenity))?> <?=e((string)$amenity['name'])?></span><?php endforeach;?></div></details><?php endif;?></section><?php endif;?>

        <footer class="public-footer-v5"><div><b><?=e($property)?></b><?php if($address!==''):?><span><?=e($address)?></span><?php endif;?></div><small>این صفحه برای بررسی ظرفیت و ارسال درخواست است؛ تأیید نهایی رزرو توسط پذیرش انجام می‌شود.</small></footer>
    </section><?php render_footer(true);
}
